package com.banktagfolders;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a dev client with the plugin loaded: {@code gradlew run}.
 */
public class BankTagFoldersPluginTest
{
	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BankTagFoldersPlugin.class);
		RuneLite.main(args);
	}
}

package com.banktagfolders;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Turns the claims this plugin makes about itself into something the build
 * checks.
 * <p>
 * The Plugin Hub reviews two things: that a plugin is not malicious, and that
 * it stays inside Jagex's third-party client guidelines. Both are properties of
 * the source, so both can be asserted against the source. Every rule below
 * corresponds to a statement in the README; if someone later writes code that
 * contradicts one, the build fails rather than the claim quietly going stale.
 * <p>
 * Scanning is done with comments stripped, so prose explaining a rule is never
 * mistaken for a breach of it.
 */
public class ComplianceTest
{
	private static final Path SOURCE_ROOT = Paths.get("src", "main", "java");

	private Map<String, String> sources()
	{
		try (Stream<Path> files = Files.walk(SOURCE_ROOT))
		{
			Map<String, String> out = new LinkedHashMap<>();
			for (Path p : files.filter(f -> f.toString().endsWith(".java")).collect(Collectors.toList()))
			{
				out.put(p.getFileName().toString(), stripComments(
					new String(Files.readAllBytes(p), StandardCharsets.UTF_8)));
			}
			assertTrue("no sources found under " + SOURCE_ROOT, !out.isEmpty());
			return out;
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	/** Remove block and line comments so documentation cannot trip a rule. */
	private static String stripComments(String src)
	{
		return src.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
	}

	private void forbid(String why, String... patterns)
	{
		List<String> hits = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			for (String p : patterns)
			{
				if (body.contains(p))
				{
					hits.add(name + " contains " + p);
				}
			}
		});
		assertEquals(why + " " + hits, 0, hits.size());
	}

	// ------------------------------------------------------------------
	// Plugin Hub rules
	// ------------------------------------------------------------------

	@Test
	public void usesNoReflection()
	{
		forbid("reflection is not permitted in hub plugins",
			"java.lang.reflect", "Class.forName", "setAccessible",
			"getDeclaredField", "getDeclaredMethod", "getDeclaredConstructor",
			"MethodHandles", "TypeToken");
	}

	/**
	 * The hub rejects plugins that build their own Gson: the client's instance
	 * is injectable and carries its serialisation settings, so a private one
	 * both duplicates it and drifts from it.
	 */
	@Test
	public void usesTheClientsGson()
	{
		forbid("inject the client's Gson rather than constructing one", "new Gson(");
	}

	@Test
	public void loadsNoCodeAndSpawnsNoProcesses()
	{
		forbid("no runtime code loading, native code or external processes",
			"ProcessBuilder", "Runtime.getRuntime", "System.load", "System.loadLibrary",
			"URLClassLoader", "defineClass", "ScriptEngine");
	}

	@Test
	public void touchesNoFilesystem()
	{
		forbid("everything is stored through RuneLite's ConfigManager",
			"java.io.File", "java.nio.file", "FileInputStream", "FileOutputStream",
			"FileReader", "FileWriter", "RandomAccessFile");
	}

	/** No third-party server, which is why no data-sharing warning is needed. */
	@Test
	public void makesNoNetworkCalls()
	{
		forbid("the plugin sends no data anywhere",
			"java.net.", "HttpURLConnection", "okhttp", "OkHttp", "Socket",
			"http://", "https://");
	}

	@Test
	public void addsNoThirdPartyDependencies() throws IOException
	{
		String build = new String(Files.readAllBytes(Paths.get("build.gradle")), StandardCharsets.UTF_8);
		List<String> offenders = new ArrayList<>();
		for (String line : build.split("\n"))
		{
			String t = line.trim();
			boolean declares = t.startsWith("implementation")
				|| t.startsWith("compileOnly")
				|| t.startsWith("annotationProcessor")
				|| t.startsWith("testImplementation");
			// Anything not from RuneLite, Lombok or JUnit has to be verified by
			// hand by a maintainer before the plugin can be accepted.
			if (declares && !(t.contains("net.runelite") || t.contains("lombok") || t.contains("junit")))
			{
				offenders.add(t);
			}
		}
		assertEquals("unexpected dependency " + offenders, 0, offenders.size());
	}

	// ------------------------------------------------------------------
	// Jagex third-party client guidelines
	// ------------------------------------------------------------------

	/** No added menu entries, and no invoking existing ones programmatically. */
	@Test
	public void sendsNothingToTheServer()
	{
		forbid("the plugin must not send actions to the server",
			"createMenuEntry", "setMenuEntries", "insertMenuItem",
			"menuAction(", "invokeMenuAction");
	}

	/**
	 * Jagex protects the click zones of the 3D scene, inventory, worn equipment,
	 * spellbook and prayer book. This plugin only ever addresses the bank, so
	 * the simplest way to show it stays clear of those is to require that the
	 * bank is the only interface it names.
	 */
	@Test
	public void addressesOnlyTheBankInterface()
	{
		List<String> offenders = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			Matcher m = Pattern.compile("InterfaceID\\.([A-Za-z_]+)").matcher(body);
			while (m.find())
			{
				if (!m.group(1).equalsIgnoreCase("BANKMAIN"))
				{
					offenders.add(name + " uses InterfaceID." + m.group(1));
				}
			}
		});
		assertEquals("only the bank may be addressed " + offenders, 0, offenders.size());
	}

	// ------------------------------------------------------------------
	// Threading and wiring
	// ------------------------------------------------------------------

	/**
	 * Calling into Client from an AWT thread throws, and the exception is
	 * swallowed, so the feature silently does nothing. Nothing here is reachable
	 * from AWT today; this keeps it that way.
	 */
	@Test
	public void keepsClientCallsOffAwtThreads()
	{
		List<String> offenders = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			boolean awtFacing = body.contains("javax.swing")
				|| body.contains("java.awt.event")
				|| body.contains("MouseListener")
				|| body.contains("KeyListener")
				|| body.contains("HotkeyListener");
			if (awtFacing && body.contains("net.runelite.api.Client"))
			{
				offenders.add(name);
			}
		});
		assertEquals("AWT-facing classes must reach the client via ClientThread " + offenders,
			0, offenders.size());
	}

	/**
	 * State injected in more than one place has to be a singleton, or each
	 * injection point silently gets its own copy and the wiring does nothing.
	 * The plugin class is excluded: RuneLite manages its lifetime.
	 */
	@Test
	public void sharedStateIsSingleton()
	{
		List<String> offenders = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			if (name.equals("BankTagFoldersPlugin.java") || !body.contains("@Inject"))
			{
				return;
			}
			if (!body.contains("@Singleton"))
			{
				offenders.add(name);
			}
		});
		assertEquals("injected collaborators must be @Singleton " + offenders, 0, offenders.size());
	}
}

package com.banktagfolders;

import com.google.inject.Provides;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuEntry;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetDrag;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;

/**
 * Folders for bank tag tabs.
 * <p>
 * Requires the core Bank Tags plugin to be <em>enabled</em> -- it owns the tags,
 * the layouts and the sprites, and most of its bank-item behaviour keeps
 * working through it -- but with its own tab strip <em>switched off</em>, since
 * both strips build their widgets in the same place. The plugin stays dormant
 * and says so rather than fighting for the space.
 * <p>
 * The event wiring mirrors {@code TabInterface} deliberately, down to doing the
 * work in {@code ScriptPreFired} for {@code BANKMAIN_FINISHBUILDING}: the
 * bank's scroll height is still an argument on the interpreter stack at that
 * point, and the tag-tab overview needs to overwrite it.
 */
@Slf4j
@PluginDescriptor(
	name = "Bank Tag Folders",
	description = "Group bank tag tabs into collapsible folders",
	tags = {"bank", "tag", "tags", "tab", "tabs", "folder", "folders", "organise", "organize"}
)
public class BankTagFoldersPlugin extends Plugin
{
	/** Argument offset of the scroll height in bankmain_finishbuilding. */
	private static final int SCROLL_HEIGHT_ARG = 9;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private FolderTree tree;

	@Inject
	private CoreBankTags core;

	@Inject
	private TagColumn column;

	@Inject
	private ColumnActions actions;

	@Inject
	private ChatMessageManager chatMessageManager;

	/** So the "turn the core strip off" nudge is said once, not every bank open. */
	private boolean warned;

	@Provides
	BankTagFoldersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankTagFoldersConfig.class);
	}

	@Override
	protected void startUp()
	{
		clientThread.invoke(() ->
		{
			tree.load();
			warned = false;
			// The bank may already be open when the plugin is enabled.
			if (canRender() && client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER) != null)
			{
				column.rebuild();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(column::deinit);
	}

	/**
	 * Whether we should be drawing at all.
	 * <p>
	 * Deliberately not something we fix by writing to the core plugin's config:
	 * silently flipping another plugin's setting is the kind of surprise that is
	 * hard to attribute later.
	 */
	private boolean canRender()
	{
		if (!core.isAvailable())
		{
			return false;
		}

		if (core.isCoreStripEnabled())
		{
			if (!warned)
			{
				warned = true;
				chatMessageManager.queue(QueuedMessage.builder()
					.type(ChatMessageType.CONSOLE)
					.runeLiteFormattedMessage("Bank Tag Folders is idle: turn off \"Tag tabs\" in the "
						+ "Bank Tags plugin so this plugin can draw the tag column instead.")
					.build());
			}
			return false;
		}

		warned = false;
		return true;
	}

	/** True while the core plugin's "every tab as an icon" view is open. */
	private boolean isOverviewActive()
	{
		return CoreBankTags.TAGTABS.equals(core.activeTag());
	}

	// ------------------------------------------------------------------
	// Bank lifecycle
	// ------------------------------------------------------------------

	/**
	 * Runs last of everything on this event.
	 * <p>
	 * The core layout manager and the Bank Tag Layouts plugin both lay the bank
	 * out from {@code BANKMAIN_FINISHBUILDING} too, and Bank Tag Layouts decides
	 * whether to do anything at all by reading {@code TabInterface.getActiveTag()}
	 * -- bailing out entirely when it is null. Drawing our column after both of
	 * them have had the bank keeps us out of that decision.
	 */
	@Subscribe(priority = -10)
	public void onScriptPreFired(ScriptPreFired event)
	{
		int id = event.getScriptId();

		if (id == ScriptID.BANKMAIN_INIT)
		{
			if (canRender())
			{
				boolean wasOpen = column.isInitialised();
				column.init();
				if (!wasOpen && column.isInitialised())
				{
					// Deferred rather than run inline. Reopening a tag forces a
					// bank relayout, and driving that from inside the bank's own
					// init means the layout code can run against a bank that has
					// not been filtered to the tag yet -- which makes every item
					// in the bank look like one the layout is missing.
					clientThread.invokeLater(this::restoreLastTag);
				}
			}
			return;
		}

		// Not just "are we set up" -- if the core strip has since been switched
		// back on we must stand down immediately, or both strips build into the
		// same container and fight over it every rebuild.
		if (!column.isInitialised())
		{
			return;
		}

		if (core.isCoreStripEnabled())
		{
			column.deinit();
			return;
		}

		// Note: BANKMAIN_SEARCH_TOGGLE is deliberately not handled. Core's
		// TabInterface already drops the active tag when the bank search opens,
		// and it does so whether or not its own strip is drawing -- so doing it
		// here as well only nulls TabInterface's active tag a second time, and
		// that field is what Bank Tag Layouts reads to decide whether to lay the
		// bank out at all.
		if (id == ScriptID.BANKMAIN_SIZE_CHECK)
		{
			onSizeCheck();
		}
		else if (id == ScriptID.BANKMAIN_FINISHBUILDING)
		{
			onFinishBuilding();
		}
	}

	/**
	 * Reopen whatever the bank was last showing.
	 * <p>
	 * The core strip does this in its own {@code init()}, which never runs while
	 * it is switched off -- so without this the bank falls back to the vanilla
	 * numbered tab the server resyncs, and a tag that was open when the bank
	 * closed is forgotten. Nothing needs saving here; the core plugin has been
	 * recording the tag all along.
	 */
	private void restoreLastTag()
	{
		if (!core.remembersLastTab())
		{
			return;
		}

		String tab = core.lastTab();
		if (tab == null)
		{
			return;
		}

		if (actions.isPotionStoreOpen())
		{
			return;
		}

		// The server resyncs the last vanilla tab as the bank opens, and it
		// would otherwise win.
		client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);

		if (CoreBankTags.TAGTABS.equals(tab))
		{
			core.openTagTabOverview();
		}
		else if (core.hasTab(tab))
		{
			core.openTag(tab);
			// Open the folder it lives in and scroll to it, so the reopened tag
			// is visibly the active one rather than hidden inside a closed
			// folder. Deferred until the column has rows to scroll among.
			column.requestReveal(tab);
		}
		// A tag deleted since the bank was last open just falls through: opening
		// it would show an empty bank with no obvious way back.
	}

	/**
	 * Detect a bank resize, exactly as the core strip does: the script is about
	 * to resize the container, so the new size is compared against the current
	 * one and the relayout is deferred until after it has been applied.
	 */
	private void onSizeCheck()
	{
		int[] stack = client.getIntStack();
		int size = client.getIntStackSize();
		Widget widget = client.getWidget(stack[size - 5]);
		if (widget == null)
		{
			return;
		}

		int width = stack[size - 4];
		int height = stack[size - 3];
		if (widget.getWidth() != width || widget.getHeight() != height)
		{
			clientThread.invokeLater(column::relayout);
		}
	}

	private void onFinishBuilding()
	{
		boolean overview = isOverviewActive();
		if (overview)
		{
			column.hideBank();
		}

		column.rebuild();
		int overviewHeight = column.rebuildOverview(overview);

		Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (title != null)
		{
			if (overview)
			{
				title.setText("Tag tab tab");
			}
			else if (core.activeTag() != null)
			{
				title.setText("Tag tab <col=ff0000>" + core.activeTag() + "</col>");
			}
		}

		if (overview)
		{
			// The overview draws icons rather than real items, so the bank's own
			// computed scroll height is wrong. This runs before the script does,
			// so its arguments are still on the stack and can be overwritten.
			int[] stack = client.getIntStack();
			int size = client.getIntStackSize();
			stack[size - SCROLL_HEIGHT_ARG] = overviewHeight;
		}
	}

	/**
	 * Runs last on this event too, matching the pre-fire handler.
	 * <p>
	 * The core layout manager and Bank Tag Layouts both lay the bank out around
	 * these scripts; touching the column only after they are done is what keeps
	 * us out of their way.
	 */
	@Subscribe(priority = -10)
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_POPUP_TAB_DRAW && column.isInitialised())
		{
			// The storage popup covers part of the column, so the rows have to
			// be re-packed into whatever height is left.
			column.relayout();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			column.deinit();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Only settings, never our own stored structure. reconcile() saves the
		// folder tree during a render, and reacting to that would schedule
		// another render, which reconciles, which saves -- the bank rebuilding
		// itself in a circle for no reason.
		boolean ours = FolderTree.GROUP.equals(event.getGroup())
			&& !FolderTree.KEY_FOLDERS.equals(event.getKey())
			&& !FolderTree.KEY_ROOTS.equals(event.getKey());
		boolean coreTabs = BankTagsPlugin.CONFIG_GROUP.equals(event.getGroup()) && "tabs".equals(event.getKey());
		if (!ours && !coreTabs)
		{
			return;
		}

		if (coreTabs)
		{
			warned = false;
		}

		clientThread.invokeLater(() ->
		{
			if (!canRender())
			{
				column.deinit();
				return;
			}
			if (client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER) != null)
			{
				column.rebuild();
			}
		});
	}

	// ------------------------------------------------------------------
	// Dragging
	// ------------------------------------------------------------------

	/**
	 * Drops onto the column.
	 * <p>
	 * {@link WidgetDrag} carries nothing itself; the client holds what was
	 * picked up and what it was released over, which is how the core strip reads
	 * its own tab reordering.
	 */
	@Subscribe
	public void onWidgetDrag(WidgetDrag event)
	{
		if (!column.isInitialised() || !canRender())
		{
			return;
		}

		Widget dragged = client.getDraggedWidget();
		if (dragged == null)
		{
			return;
		}

		try
		{
			if (client.getMouseCurrentButton() == 0)
			{
				handleDrop(dragged, client.getDraggedOnWidget(), client.isKeyPressed(KeyCode.KC_SHIFT));
			}
			else
			{
				handleDragInProgress(dragged);
			}
		}
		catch (Exception e)
		{
			log.warn("Tag column drag failed", e);
		}
	}

	/**
	 * While the mouse is still down, keep the arrows scrolling when something is
	 * held over them.
	 * <p>
	 * Core also rewrites the pending menu entry here so a drag reads as
	 * "tag:<tab>". That is deliberately not done: this plugin already tags the
	 * item itself when the drag is released, so the rewrite would be a second
	 * route to the same result, and mutating a menu entry is exactly the kind of
	 * thing the third-party client guidelines are written about. Not doing it
	 * costs a little hover text and nothing else.
	 */
	private void handleDragInProgress(Widget dragged)
	{
		if (dragged.getItemId() == -1)
		{
			return;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}

		String option = entries[entries.length - 1].getOption();
		if (TagColumn.SCROLL_UP.equals(option))
		{
			column.scrollTick(-1);
		}
		else if (TagColumn.SCROLL_DOWN.equals(option))
		{
			column.scrollTick(1);
		}
	}

	private void handleDrop(Widget dragged, @Nullable Widget draggedOn, boolean shift)
	{
		StripRow source = column.rowFor(dragged);

		if (source == null)
		{
			tagByDrop(dragged, column.rowFor(draggedOn), shift);
			return;
		}

		TagColumn.Drop drop = column.dropAt(client.getMouseCanvasPosition());
		if (drop == null)
		{
			// Released inside the column but past the last row: send it to the
			// bottom of the top level. Released outside: just tidy up the widget
			// that was left showing at the cursor.
			if (column.containsCanvasPoint(client.getMouseCanvasPosition()))
			{
				if (source.isTag())
				{
					tree.moveToRoot(source.getTag(), -1);
				}
				else
				{
					tree.reorderRoot(tree.rootKey(source), -1);
				}
			}
			column.rebuild();
			return;
		}

		if (source.isTag())
		{
			dropTag(source, drop);
		}
		else
		{
			dropFolder(source, drop);
		}
	}

	/** A bank item dragged onto a tab tags it, as the core strip allows. */
	private void tagByDrop(Widget dragged, @Nullable StripRow target, boolean shift)
	{
		if (target == null || !target.isTag())
		{
			return;
		}

		// Dynamic children report their parent's packed id, so this is "an item
		// from the bank's item list" rather than any item widget anywhere.
		if (dragged.getId() != InterfaceID.Bankmain.ITEMS || dragged.getItemId() == -1)
		{
			return;
		}

		core.tagItem(dragged.getItemId(), target.getTag(), shift);
		core.reloadActiveTab();
		column.rebuild();
	}

	private void dropTag(StripRow source, TagColumn.Drop drop)
	{
		String tag = source.getTag();
		StripRow target = drop.getRow();
		TagColumn.DropZone zone = drop.getZone();

		if (target.sameAs(source))
		{
			column.rebuild();
			return;
		}

		if (target.isFolder())
		{
			Folder folder = target.getFolder();
			if (zone == TagColumn.DropZone.INTO)
			{
				tree.moveIntoFolder(tag, folder.getId(), -1);
				// Expanding shows the tag landing where it was put, instead of
				// it seeming to vanish into a closed folder.
				if (folder.isCollapsed())
				{
					tree.toggleCollapsed(folder.getId());
				}
			}
			else if (zone == TagColumn.DropZone.BEFORE)
			{
				tree.moveTagNear(tag, target, false);
			}
			else if (folder.isCollapsed())
			{
				tree.moveTagNear(tag, target, true);
			}
			else
			{
				// Just below an open folder's header reads as "first one inside".
				tree.moveIntoFolder(tag, folder.getId(), 0);
			}

			column.rebuild();
			return;
		}

		Folder targetFolder = target.getParent();

		if (zone == TagColumn.DropZone.INTO)
		{
			if (targetFolder != null)
			{
				tree.moveTagIntoFolderNear(tag, targetFolder.getId(), target.getTag(), true);
				column.rebuild();
			}
			else
			{
				// Two loose tabs dropped together: the phone-homescreen gesture.
				// The tabs only move once the folder has been named, so backing
				// out of the prompt leaves the column as it was.
				actions.createFolderFrom(target.getTag(), tag);
			}
			return;
		}

		boolean after = zone == TagColumn.DropZone.AFTER;
		if (targetFolder != null)
		{
			tree.moveTagIntoFolderNear(tag, targetFolder.getId(), target.getTag(), after);
		}
		else
		{
			tree.moveTagNear(tag, target, after);
		}
		column.rebuild();
	}

	private void dropFolder(StripRow source, TagColumn.Drop drop)
	{
		StripRow target = drop.getRow();
		Folder folder = source.getFolder();

		// Dropping a folder onto its own contents would ask it to reorder
		// relative to itself.
		if (target.sameAs(source)
			|| (target.getParent() != null && target.getParent().getId().equals(folder.getId())))
		{
			column.rebuild();
			return;
		}

		// Folders reorder only. Nesting one inside another has no way to be
		// drawn, so a drop into the middle of a row is treated as "after it".
		tree.moveFolderNear(folder.getId(), target, drop.getZone() != TagColumn.DropZone.BEFORE);
		column.rebuild();
	}
}

package com.banktagfolders;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(FolderTree.GROUP)
public interface BankTagFoldersConfig extends Config
{
	/**
	 * The tab background sprite is 40 pixels tall and is drawn tiled, so a taller
	 * row repeats it and shows the top edge of a second tab inside the first.
	 */
	int MAX_ROW_HEIGHT = 40;


	@ConfigItem(
		keyName = "tagRowHeight",
		name = "Tag row height",
		description = "Height of a row, folders included. 24 to 40, since the game's tab background is itself 40"
			+ " tall and repeats above that. Smaller fits more rows on screen.",
		position = 2
	)
	@Range(min = 24, max = MAX_ROW_HEIGHT)
	default int tagRowHeight()
	{
		return 40;
	}

	@ConfigItem(
		keyName = "tagTintStrength",
		name = "Tag tint strength",
		description = "How strongly a folder's colour tints the tag tabs inside it."
			+ " Zero leaves them looking like ordinary tabs.",
		position = 4
	)
	@Range(max = 100)
	default int tagTintStrength()
	{
		return 35;
	}

	@ConfigItem(
		keyName = "folderTintStrength",
		name = "Folder tint strength",
		description = "How strongly a folder's colour fills the folder's own row."
			+ " Zero leaves only the icon and the expand marker.",
		position = 5
	)
	@Range(max = 100)
	default int folderTintStrength()
	{
		return 68;
	}

	@ConfigItem(
		keyName = "protectLayoutSpacing",
		name = "Protect layout spacing",
		description = "Off by default, matching the Bank Tags plugin exactly: tagged items that are not in a tab's"
			+ " layout yet drop into the first free slots, from the top."
			+ "<br><br>Turn this on only if you deliberately leave blank slots as spacing and want them left alone --"
			+ " unlaid items are then appended below the layout instead. If your tabs rely on those items landing"
			+ " in the blanks, this will look wrong.",
		position = 6
	)
	default boolean protectLayoutSpacing()
	{
		// Deliberately matching core rather than "protecting" by default. A tab
		// whose blank slots are where its untracked items are *meant* to land
		// renders wrong the moment they are appended instead -- which is not a
		// trade to make on a player's behalf without them asking.
		return false;
	}
}

package com.banktagfolders;

import javax.annotation.Nullable;

/**
 * One row of the tag column: either a folder header or a tag tab.
 * <p>
 * Rows are derived fresh from {@link FolderTree} on every render and thrown
 * away afterwards. They exist so the renderer and the drag handler agree on
 * what a given widget represents without either of them re-walking the tree.
 */
class StripRow
{
	enum Kind
	{
		FOLDER,
		TAG
	}

	private final Kind kind;

	@Nullable
	private final String tag;

	@Nullable
	private final Folder folder;

	/** The folder this tag sits inside, or null when the tag is top level. */
	@Nullable
	private final Folder parent;

	private StripRow(Kind kind, @Nullable String tag, @Nullable Folder folder, @Nullable Folder parent)
	{
		this.kind = kind;
		this.tag = tag;
		this.folder = folder;
		this.parent = parent;
	}

	static StripRow folder(Folder folder)
	{
		return new StripRow(Kind.FOLDER, null, folder, null);
	}

	static StripRow tag(String tag, @Nullable Folder parent)
	{
		return new StripRow(Kind.TAG, tag, null, parent);
	}

	boolean isFolder()
	{
		return kind == Kind.FOLDER;
	}

	boolean isTag()
	{
		return kind == Kind.TAG;
	}

	/** True when this tag is nested, and so should be drawn indented. */
	boolean isNested()
	{
		return parent != null;
	}

	@Nullable
	String getTag()
	{
		return tag;
	}

	@Nullable
	Folder getFolder()
	{
		return folder;
	}

	@Nullable
	Folder getParent()
	{
		return parent;
	}

	/**
	 * Whether two rows stand for the same thing.
	 * <p>
	 * Compared by what they name rather than by identity: rows are rebuilt from
	 * scratch on every render, so two objects describing the same tab are
	 * routine.
	 */
	boolean sameAs(@Nullable StripRow other)
	{
		if (other == null || other.kind != kind)
		{
			return false;
		}
		if (kind == Kind.FOLDER)
		{
			return folder.getId().equals(other.folder.getId());
		}
		return tag.equals(other.tag);
	}
}

package com.banktagfolders;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsConfig;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.Text;

/**
 * Everything this plugin needs from the core Bank Tags plugin, in one place.
 * <p>
 * The core plugin stays the single source of truth for which tags exist, which
 * items carry them, what icon each one uses and what layout it has. This class
 * reads that state and asks the core plugin to act on it; it never keeps a
 * second copy.
 * <p>
 * Config is the durable store for the tab list, so config is what we read.
 * The core plugin's {@code TabManager} is an in-memory mirror filled by
 * {@code TabInterface.init()}, which never runs while the core strip is off --
 * so it cannot be read from, but it does have to be written to, because other
 * plugins consult it. See {@link #syncTabManager()}.
 * <p>
 * Nothing here is injectable the ordinary way either. {@code BankTagsService}
 * is an interface with no binding a side-loaded plugin's child injector can
 * see, and the managers are client-classloader singletons, so all of them are
 * resolved at runtime and every accessor degrades rather than throwing.
 */
@Slf4j
@Singleton
public class CoreBankTags
{
	/** The core plugin's name for its "show me every tab" pseudo-tag. */
	static final String TAGTABS = "tagtabs";

	private final PluginManager pluginManager;
	private final ConfigManager configManager;
	private final BankTagFoldersConfig config;

	@Nullable
	private BankTagsService service;

	@Nullable
	private TagManager tagManager;

	@Nullable
	private LayoutManager layoutManager;

	@Nullable
	private BankSearch bankSearch;

	@Nullable
	private TabManager tabManager;

	@Inject
	CoreBankTags(PluginManager pluginManager, ConfigManager configManager, BankTagFoldersConfig config)
	{
		this.pluginManager = pluginManager;
		this.configManager = configManager;
		this.config = config;
	}

	/**
	 * The core plugin, found among the loaded plugins because it implements the
	 * service interface itself.
	 */
	@Nullable
	BankTagsService service()
	{
		if (service == null)
		{
			for (Plugin plugin : pluginManager.getPlugins())
			{
				if (plugin instanceof BankTagsService)
				{
					service = (BankTagsService) plugin;
					break;
				}
			}
		}
		return service;
	}

	/**
	 * Resolve one of the core plugin's collaborators.
	 * <p>
	 * Asked of the <em>Bank Tags plugin's own injector</em>, not the root one.
	 * Every plugin gets a child injector, and the core plugin's collaborators
	 * are just-in-time bound there -- {@code LayoutManager} necessarily so,
	 * since it depends on {@code BankTagsPlugin} itself, which the root injector
	 * has no binding for. Asking the root throws outright:
	 * <p>
	 * {@code Unable to create binding for LayoutManager. It was already
	 * configured on one or more child injectors}
	 * <p>
	 * The child also delegates to the root for anything it does not own, so this
	 * resolves everything the root could <em>and</em> guarantees we share the
	 * core plugin's own instances rather than quietly constructing a second set
	 * of singletons alongside them.
	 */
	@Nullable
	private <T> T resolve(Class<T> type)
	{
		BankTagsService bankTags = service();
		if (bankTags instanceof Plugin)
		{
			try
			{
				return ((Plugin) bankTags).getInjector().getInstance(type);
			}
			catch (Exception e)
			{
				log.debug("Could not resolve {} from the Bank Tags injector", type.getSimpleName(), e);
			}
		}

		try
		{
			return RuneLite.getInjector().getInstance(type);
		}
		catch (Exception e)
		{
			log.warn("Could not resolve {}", type.getSimpleName(), e);
			return null;
		}
	}

	@Nullable
	TagManager tagManager()
	{
		if (tagManager == null)
		{
			tagManager = resolve(TagManager.class);
		}
		return tagManager;
	}

	@Nullable
	LayoutManager layoutManager()
	{
		if (layoutManager == null)
		{
			layoutManager = resolve(LayoutManager.class);
		}
		return layoutManager;
	}

	@Nullable
	BankSearch bankSearch()
	{
		if (bankSearch == null)
		{
			bankSearch = resolve(BankSearch.class);
		}
		return bankSearch;
	}

	@Nullable
	TabManager tabManager()
	{
		if (tabManager == null)
		{
			tabManager = resolve(TabManager.class);
		}
		return tabManager;
	}

	boolean isAvailable()
	{
		return service() != null;
	}

	/**
	 * Whether the core plugin is still drawing its own tag column.
	 * <p>
	 * We stay dormant while it is: both strips build their widgets as dynamic
	 * children of the same bank container, and would delete each other's on
	 * every rebuild.
	 */
	boolean isCoreStripEnabled()
	{
		BankTagsConfig config = configManager.getConfig(BankTagsConfig.class);
		// The core default is on, so an unreadable proxy has to count as "on"
		// too -- drawing over a live strip is the worse failure.
		return config == null || config.tabs();
	}

	/**
	 * Whether the core plugin is set to reopen the last tag with the bank.
	 * <p>
	 * Honoured rather than duplicated: it is the same feature, it has always
	 * lived in Bank Tags, and a second setting of the same name in a second
	 * plugin would be a coin toss as to which one a player reaches for.
	 */
	boolean remembersLastTab()
	{
		BankTagsConfig config = configManager.getConfig(BankTagsConfig.class);
		return config == null || config.rememberTab();
	}

	/**
	 * The tag the bank was last showing.
	 * <p>
	 * Already written for us: the core plugin records it whenever a tag is
	 * opened or closed, and that happens through {@code BankTagsPlugin.openTag}
	 * regardless of whether its own strip is drawing. Closing the bank passes a
	 * null tag, which returns before touching the setting -- so the value
	 * survives, and only the restoring half was missing.
	 */
	@Nullable
	String lastTab()
	{
		BankTagsConfig config = configManager.getConfig(BankTagsConfig.class);
		if (config == null)
		{
			return null;
		}
		String tab = config.tab();
		return tab == null || tab.isEmpty() ? null : tab;
	}

	// ------------------------------------------------------------------
	// Tab list
	// ------------------------------------------------------------------

	/** Tag names, in the order the core plugin stores them. */
	List<String> tagTabs()
	{
		String csv = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG);
		if (csv == null || csv.isEmpty())
		{
			return new ArrayList<>();
		}
		return new ArrayList<>(Text.fromCSV(csv));
	}

	void setTagTabs(List<String> tags)
	{
		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tags));
	}

	boolean hasTab(String tag)
	{
		return tagTabs().contains(Text.standardize(tag));
	}

	/**
	 * Mirror the tab list into the core plugin's {@code TabManager}.
	 * <p>
	 * {@code TabManager} is normally filled by {@code TabInterface.init()},
	 * which only runs while the core strip is drawing. With the strip off it
	 * stays empty -- and it is not private bookkeeping: other plugins read it as
	 * the answer to "does this tag tab exist?".
	 * <p>
	 * Bank Tag Layouts is the one that matters here. Its
	 * {@code isVanillaLayoutEnabled()} does {@code tabManager.find(tag) != null
	 * && hasRuneliteLayout(tag)} to decide whether the core layout engine owns a
	 * tab. Against an empty TabManager that is always false, so it concludes the
	 * core engine is not involved and lays the bank out itself -- on top of the
	 * core layout manager, which is still laying out the same tab. Two engines,
	 * one bank, and the duplicate entries lose.
	 * <p>
	 * Taking over the strip means taking over this too.
	 */
	void syncTabManager()
	{
		TabManager tabs = tabManager();
		if (tabs == null)
		{
			return;
		}

		try
		{
			List<String> live = tagTabs();
			List<TagTab> current = tabs.getTabs();

			// Cheap identity check first: this runs on every bank build and the
			// list almost never changes.
			if (current.size() == live.size())
			{
				boolean same = true;
				for (int i = 0; i < live.size(); i++)
				{
					if (!live.get(i).equals(current.get(i).getTag()))
					{
						same = false;
						break;
					}
				}
				if (same)
				{
					return;
				}
			}

			// Rebuilt in the config's own order, so a TabManager.save() by
			// anything else writes back exactly what is already stored.
			current.clear();
			for (String tag : live)
			{
				TagTab tab = new TagTab();
				tab.setTag(tag);
				tab.setIconItemId(iconFor(tag));
				current.add(tab);
			}
		}
		catch (Exception e)
		{
			log.warn("Could not mirror the tab list into the core TabManager", e);
		}
	}


	/** Create a tab if it does not already exist. Returns false when taken. */
	boolean createTab(String tag)
	{
		String name = Text.standardize(tag);
		List<String> tabs = tagTabs();
		if (name.isEmpty() || tabs.contains(name))
		{
			return false;
		}
		tabs.add(name);
		setTagTabs(tabs);
		return true;
	}

	/**
	 * Delete the tab, its icon and its layout, leaving the tag on items.
	 * <p>
	 * The core plugin offers this separately from removing the tag itself, and
	 * the distinction matters: one is cosmetic, the other is destructive.
	 */
	void removeTabOnly(String tag)
	{
		List<String> tabs = tagTabs();
		if (tabs.remove(tag))
		{
			setTagTabs(tabs);
		}

		unsetIcon(tag);

		LayoutManager layouts = layoutManager();
		if (layouts != null)
		{
			layouts.removeLayout(tag);
		}
	}

	/** Strip a tag from every item carrying it. */
	void removeTagFromItems(String tag)
	{
		TagManager tags = tagManager();
		if (tags != null)
		{
			tags.removeTag(tag);
		}
	}

	// ------------------------------------------------------------------
	// Icons
	// ------------------------------------------------------------------

	/** Item id drawn on a tag's tab, or 0 when it has never been given one. */
	int iconFor(String tag)
	{
		String value = configManager.getConfiguration(
			BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + Text.standardize(tag));
		if (value == null)
		{
			return 0;
		}
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	void setIcon(String tag, int itemId)
	{
		configManager.setConfiguration(
			BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + Text.standardize(tag), itemId);
	}

	void unsetIcon(String tag)
	{
		configManager.unsetConfiguration(
			BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + Text.standardize(tag));
	}

	// ------------------------------------------------------------------
	// Layouts
	// ------------------------------------------------------------------

	/**
	 * Whether a tag has a layout, without parsing it.
	 * <p>
	 * The column asks this once per row on every bank rebuild, purely to label a
	 * menu option "Enable" or "Disable layout". {@code loadLayout} would read the
	 * config and parse the whole stored layout -- several hundred integers for a
	 * large tab -- to answer a yes/no question, and the bank rebuilds on every
	 * keystroke in its search box.
	 */
	boolean hasLayout(String tag)
	{
		return configManager.getConfiguration(
			BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_LAYOUT_PREFIX + Text.standardize(tag)) != null;
	}

	@Nullable
	Layout loadLayout(String tag)
	{
		LayoutManager layouts = layoutManager();
		return layouts == null ? null : layouts.loadLayout(tag);
	}

	void saveLayout(Layout layout)
	{
		LayoutManager layouts = layoutManager();
		if (layouts != null)
		{
			layouts.saveLayout(layout);
		}
	}

	void removeLayout(String tag)
	{
		LayoutManager layouts = layoutManager();
		if (layouts != null)
		{
			layouts.removeLayout(tag);
		}
	}

	// ------------------------------------------------------------------
	// Item tags
	// ------------------------------------------------------------------

	/** @param variation tag every variant of the item, as shift-drag does */
	void tagItem(int itemId, String tag, boolean variation)
	{
		TagManager tags = tagManager();
		if (tags != null)
		{
			tags.addTag(itemId, tag, variation);
		}
	}

	List<Integer> itemsForTag(String tag)
	{
		TagManager tags = tagManager();
		return tags == null ? new ArrayList<>() : tags.getItemsForTag(tag);
	}

	void renameTagOnItems(String from, String to)
	{
		TagManager tags = tagManager();
		if (tags != null)
		{
			tags.renameTag(from, to);
		}
	}

	// ------------------------------------------------------------------
	// Opening tags
	// ------------------------------------------------------------------

	@Nullable
	String activeTag()
	{
		BankTagsService bankTags = service();
		return bankTags == null ? null : bankTags.getActiveTag();
	}

	/**
	 * Open a tag, layout and all.
	 * <p>
	 * {@code openBankTag} loads the tag's layout itself unless told not to, and
	 * routes through the core plugin's own {@code openTag} -- which also sets
	 * the state its Remove-tag, Duplicate-item and Tag-inventory menu entries
	 * read. Those keep working with the core strip switched off precisely
	 * because we go through here rather than filtering the bank ourselves.
	 */
	void openTag(String tag)
	{
		BankTagsService bankTags = service();
		if (bankTags == null)
		{
			return;
		}

		int options = BankTagsService.OPTION_ALLOW_MODIFICATIONS;
		if (config.protectLayoutSpacing())
		{
			// Without this, a tagged item that is not in the tab's layout yet is
			// dropped into the first free slot -- starting from the very top --
			// and the layout is then saved. Any blank slots left as deliberate
			// spacing get eaten permanently. This option appends such items
			// after the last one instead, so an arranged tab stays arranged.
			options |= BankTagsService.OPTION_ITEMS_NOT_IN_LAYOUT_AT_BOTTOM;
		}

		bankTags.openBankTag(tag, options);
	}

	/** Open the core plugin's "every tab as an icon" pseudo-tag. */
	void openTagTabOverview()
	{
		BankTagsService bankTags = service();
		if (bankTags != null)
		{
			bankTags.openBankTag(TAGTABS, 0);
		}
	}

	void closeTag()
	{
		BankTagsService bankTags = service();
		if (bankTags != null)
		{
			bankTags.closeBankTag();
		}
	}

	/** Re-apply the active tag's filter after its contents changed. */
	void reloadActiveTab()
	{
		String tag = activeTag();
		if (tag != null)
		{
			openTag(tag);
		}
	}

	void relayoutBank()
	{
		BankSearch search = bankSearch();
		if (search != null)
		{
			search.layoutBank();
		}
	}

	void resetBank()
	{
		BankSearch search = bankSearch();
		if (search != null)
		{
			search.reset(true);
		}
	}
}

package com.banktagfolders;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * A named, collapsible group of bank tags.
 * <p>
 * Folders live entirely in this plugin's own config group. Nothing about them
 * is written back into {@code banktags}, so turning this plugin off leaves the
 * player with exactly the flat tag list they had before -- no orphaned
 * pseudo-tabs, no reordering, nothing to clean up.
 */
@Data
public class Folder
{
	/**
	 * Stable identity, generated once at creation.
	 * <p>
	 * Deliberately not the folder's name: renaming has to be a pure relabel, and
	 * keying on the name would orphan every row pointing at the old one.
	 */
	private String id;

	private String name;

	/**
	 * Item sprite drawn on the folder row. Zero means "borrow the icon of the
	 * first tag inside", which keeps a freshly dragged-together folder from
	 * showing up blank before the player has picked anything.
	 */
	private int iconItemId;

	private boolean collapsed;

	/**
	 * Row colour as 0xRRGGBB, shared with every tag inside the folder.
	 * <p>
	 * Colour is what marks membership, rather than indenting the member rows.
	 * The column is only 39px wide and an item sprite is 36 of them, so an
	 * indent large enough to notice also pushed the icon off the edge.
	 * <p>
	 * Zero means one has not been chosen, and a palette colour is assigned.
	 */
	private int color;

	/** Member tags, in display order. */
	private List<String> tags = new ArrayList<>();
}

