/**
 * Every menu option the column offers.
 * <p>
 * The tag options are ports of {@code TabInterface.opTagTab} and its helpers,
 * kept deliberately close to the originals -- including the wording of the
 * chat messages and the shape of the confirmation menus -- so that anyone
 * moving from the stock strip finds the same behaviour. The folder options are
 * ours.
 */
@Slf4j
@Singleton
public class ColumnActions
{
	/**
	 * The bank tab varbit value meaning "potion store". Core reads this from
	 * {@code PotionStorage}, whose constant is package-private, so it is
	 * restated here rather than reached for reflectively.
	 */
	private static final int BANKTAB_POTIONSTORE = 15;

	private final Client client;
	private final ClientThread clientThread;
	private final FolderTree tree;
	private final CoreBankTags core;
	private final ChatboxPanelManager chatboxPanelManager;
	private final Provider<ChatboxItemSearch> itemSearch;
	private final ChatMessageManager chatMessageManager;
	private final Provider<TagColumn> column;

	@Inject
	ColumnActions(Client client, ClientThread clientThread, FolderTree tree, CoreBankTags core,
		ChatboxPanelManager chatboxPanelManager, Provider<ChatboxItemSearch> itemSearch,
		ChatMessageManager chatMessageManager, Provider<TagColumn> column)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.tree = tree;
		this.core = core;
		this.chatboxPanelManager = chatboxPanelManager;
		this.itemSearch = itemSearch;
		this.chatMessageManager = chatMessageManager;
		this.column = column;
	}

	// ------------------------------------------------------------------
	// Tag tab options
	// ------------------------------------------------------------------

	void onTagOp(int op, StripRow row)
	{
		String tag = row.getTag();
		try
		{
			switch (op)
			{
				case TagColumn.TAB_OP_OPEN_TAG:
					openTag(tag);
					break;
				case TagColumn.TAB_OP_CHANGE_ICON:
					changeTagIcon(tag);
					break;
				case TagColumn.TAB_OP_LAYOUT:
					toggleLayout(tag);
					break;
				case TagColumn.TAB_OP_EXPORT_TAB:
					exportTab(tag);
					break;
				case TagColumn.TAB_OP_RENAME_TAB:
					renameTab(tag);
					break;
				case TagColumn.TAB_OP_DELETE_TAB:
					confirmDeleteTab(tag);
					break;
				case TagColumn.TAB_OP_UNFILE:
					unfile(row);
					break;
				default:
					break;
			}
		}
		catch (Exception e)
		{
			log.warn("Tag option {} on '{}' failed", op, tag, e);
		}
	}

	private void openTag(String tag)
	{
		if (isPotionStoreOpen())
		{
			sayPotionStoreIsOpen();
			return;
		}
		client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);

		if (tag.equals(core.activeTag()))
		{
			core.closeTag();
			core.resetBank();
		}
		else
		{
			core.openTag(tag);
		}

		client.playSoundEffect(SoundEffectID.UI_BOOP);
	}

	private void changeTagIcon(String tag)
	{
		itemSearch.get()
			.tooltipText("Change icon (" + tag + ")")
			.onItemSelected(itemId -> clientThread.invokeLater(() ->
			{
				core.setIcon(tag, itemId);
				column.get().rebuild();
			}))
			.build();
	}

	/**
	 * Turn layout mode on or off for a tag.
	 * <p>
	 * With layout mode on, the core plugin's own Duplicate-item and
	 * Remove-layout entries appear on the bank items -- those are added by
	 * {@code TabInterface.onMenuEntryAdded}, which is not gated on the strip
	 * being enabled, so the per-tab editor keeps working through this plugin.
	 */
	private void toggleLayout(String tag)
	{
		Layout layout = core.loadLayout(tag);

		if (layout == null)
		{
			layout = new Layout(tag);
			core.saveLayout(layout);
			say("Tag tab '" + tag + "' is now in layout mode. You may reorder the items without changing their order in the bank.");
		}
		else
		{
			core.removeLayout(tag);
			layout = null;
			say("Tag tab '" + tag + "' is no longer in layout mode");
		}

		if (tag.equals(core.activeTag()))
		{
			core.openTag(tag);
		}

		core.relayoutBank();
		column.get().rebuild();
	}

	private void exportTab(String tag)
	{
		List<String> data = new ArrayList<>();
		Layout layout = core.loadLayout(tag);

		data.add("banktags");
		data.add("1");
		data.add(tag);
		data.add(String.valueOf(core.iconFor(tag)));

		for (Integer item : core.itemsForTag(tag))
		{
			// Items placed by the layout are written in the layout section
			// instead, so they are not listed twice.
			if (layout == null || layout.count(item) == 0)
			{
				data.add(String.valueOf(item));
			}
		}

		if (layout != null)
		{
			data.add("layout");
			int[] l = layout.getLayout();
			for (int idx = 0; idx < l.length; ++idx)
			{
				if (l[idx] != -1)
				{
					data.add(String.valueOf(idx));
					data.add(String.valueOf(l[idx]));
				}
			}
		}

		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(Text.toCSV(data)), null);
		say("Tag tab '" + tag + "' has been copied to your clipboard!");
	}

	private void renameTab(String oldTag)
	{
		chatboxPanelManager.openTextInput("Enter new tag name for tag \"" + oldTag + "\":")
			.addCharValidator(TabInterface.FILTERED_CHARS)
			.onDone((Consumer<String>) value -> clientThread.invoke(() -> doRename(oldTag, value)))
			.build();
	}

	private void doRename(String oldTag, String value)
	{
		String newTag = Text.standardize(value);
		if (newTag.isEmpty() || newTag.equalsIgnoreCase(oldTag))
		{
			return;
		}

		if (core.hasTab(newTag))
		{
			chatboxPanelManager.openTextMenuInput("The specified bank tag already exists.")
				.option("1. Merge into existing tag \"" + newTag + "\".",
					() -> clientThread.invoke(() -> mergeTab(oldTag, newTag)))
				.option("2. Choose a different name.",
					() -> clientThread.invoke(() -> renameTab(oldTag)))
				.build();
			return;
		}

		List<String> tabs = core.tagTabs();
		int at = tabs.indexOf(oldTag);
		if (at < 0)
		{
			return;
		}

		// Read the old tab's belongings before anything is unset, or the icon
		// and layout are gone by the time they need re-filing under the new name.
		int icon = core.iconFor(oldTag);
		Layout layout = core.loadLayout(oldTag);

		tabs.set(at, newTag);
		core.setTagTabs(tabs);

		core.unsetIcon(oldTag);
		core.removeLayout(oldTag);

		if (icon > 0)
		{
			core.setIcon(newTag, icon);
		}
		if (layout != null)
		{
			core.saveLayout(new Layout(newTag, layout.getLayout()));
		}

		core.renameTagOnItems(oldTag, newTag);

		// Carry the tab's place in its folder across, so renaming does not
		// quietly drop it to the bottom of the column.
		tree.renameTag(oldTag, newTag);

		column.get().rebuild();
		core.reloadActiveTab();
	}

	private void mergeTab(String oldTag, String newTag)
	{
		boolean wasActive = oldTag.equals(core.activeTag());

		core.renameTagOnItems(oldTag, newTag);
		core.removeTabOnly(oldTag);

		if (wasActive)
		{
			core.openTag(newTag);
		}
		else
		{
			core.reloadActiveTab();
		}

		column.get().rebuild();
	}

	private void confirmDeleteTab(String tag)
	{
		chatboxPanelManager.openTextMenuInput("Delete " + tag)
			.option("1. Tab and tag from all items", () -> clientThread.invoke(() ->
			{
				core.removeTagFromItems(tag);
				deleteTab(tag);
			}))
			.option("2. Only tab", () -> clientThread.invoke(() -> deleteTab(tag)))
			.option("3. Cancel", () ->
			{
			})
			.build();
	}

	private void deleteTab(String tag)
	{
		if (tag.equals(core.activeTag()))
		{
			// Leaving the bank filtered by a tag that no longer exists shows an
			// empty bank with no obvious way back.
			core.closeTag();
			core.resetBank();
		}

		core.removeTabOnly(tag);
		column.get().rebuild();
	}

	private void unfile(StripRow row)
	{
		Folder folder = row.getParent();
		if (folder == null)
		{
			return;
		}

		// Lands directly under the folder it came out of, which is where the
		// eye is already looking.
		int at = tree.rootIndexOf(StripRow.folder(folder));
		tree.moveToRoot(row.getTag(), at < 0 ? -1 : at + 1);
		column.get().rebuild();
	}

	// ------------------------------------------------------------------
	// Folder options
	// ------------------------------------------------------------------

	void onFolderOp(int op, StripRow row)
	{
		Folder folder = row.getFolder();
		try
		{
			switch (op)
			{
				case TagColumn.FOLDER_OP_TOGGLE:
					tree.toggleCollapsed(folder.getId());
					column.get().rebuild();
					break;

				case TagColumn.FOLDER_OP_CHANGE_ICON:
					itemSearch.get()
						.tooltipText("Change icon (" + folder.getName() + ")")
						.onItemSelected(itemId -> clientThread.invokeLater(() ->
						{
							tree.setIcon(folder.getId(), itemId);
							column.get().rebuild();
						}))
						.build();
					break;

				case TagColumn.FOLDER_OP_SET_COLOUR:
					setFolderColour(folder);
					break;

				case TagColumn.FOLDER_OP_RENAME:
					promptName("Enter new name for folder \"" + folder.getName() + "\":", name ->
					{
						tree.rename(folder.getId(), name);
						column.get().rebuild();
					});
					break;

				case TagColumn.FOLDER_OP_DELETE:
					// Only the grouping goes; the tabs inside spill back out
					// where the folder stood. Nothing here can lose a tag.
					tree.dissolve(folder.getId());
					column.get().rebuild();
					break;

				default:
					break;
			}
		}
		catch (Exception e)
		{
			log.warn("Folder option {} failed", op, e);
		}
	}

	/**
	 * Ask for a colour as hex. There is no colour picker reachable from the
	 * bank, and the chatbox is already how this plugin asks for names.
	 */
	private void setFolderColour(Folder folder)
	{
		chatboxPanelManager.openTextInput("Folder colour as hex (e.g. 3a6b8b):")
			.addCharValidator(TabInterface.FILTERED_CHARS)
			.onDone((Consumer<String>) value -> clientThread.invoke(() ->
			{
				Integer rgb = parseHexColour(value);
				if (rgb == null)
				{
					say("That is not a hex colour. Try six hex digits, like 3a6b8b.");
					return;
				}
				tree.setColor(folder.getId(), rgb);
				column.get().rebuild();
			}))
			.build();
	}

	/** Accepts rgb or rrggbb, with or without a leading hash. */
	private Integer parseHexColour(String value)
	{
		String hex = value == null ? "" : value.trim().replace("#", "");
		if (hex.length() == 3)
		{
			StringBuilder expanded = new StringBuilder();
			for (char c : hex.toCharArray())
			{
				expanded.append(c).append(c);
			}
			hex = expanded.toString();
		}

		if (hex.length() != 6)
		{
			return null;
		}

		try
		{
			return Integer.parseInt(hex, 16);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Two tabs dragged together become a folder, once it has a name. */
	void createFolderFrom(String target, String dragged)
	{
		promptName("Name the new folder:", name ->
		{
			tree.createFolder(name, target, dragged);
			column.get().rebuild();
		});
	}

	// ------------------------------------------------------------------
	// New tab button
	// ------------------------------------------------------------------

	void onNewTabOp(int op)
	{
		try
		{
			switch (op)
			{
				case TagColumn.NEWTAB_OP_NEW_TAB:
					chatboxPanelManager.openTextInput("Tag name")
						.addCharValidator(TabInterface.FILTERED_CHARS)
						.onDone((Consumer<String>) value -> clientThread.invoke(() ->
						{
							String name = Text.standardize(value);
							if (!name.isEmpty() && core.createTab(name))
							{
								column.get().rebuild();
							}
						}))
						.build();
					break;

				case TagColumn.NEWTAB_OP_IMPORT_TAB:
					importTab();
					break;

				case TagColumn.NEWTAB_OP_OPEN_TAB_MENU:
					if (isPotionStoreOpen())
					{
						sayPotionStoreIsOpen();
						break;
					}
					client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);
					core.openTagTabOverview();
					break;

				case TagColumn.NEWTAB_OP_NEW_FOLDER:
					promptName("Folder name:", name ->
					{
						tree.createEmptyFolder(name);
						column.get().rebuild();
					});
					break;

				default:
					break;
			}
		}
		catch (Exception e)
		{
			log.warn("New tab option {} failed", op, e);
		}
	}

	private void importTab()
	{
		try
		{
			String dataString = Toolkit.getDefaultToolkit()
				.getSystemClipboard()
				.getData(DataFlavor.stringFlavor)
				.toString()
				.trim();

			Iterator<String> data = Text.fromCSV(dataString).iterator();
			String tag = dataString.startsWith("banktaglayoutsplugin")
				? importBankTagLayouts(data)
				: importBankTags(data);

			if (tag == null)
			{
				say("Failed to import tag tab from clipboard, invalid format.");
				return;
			}

			core.createTab(tag);
			column.get().rebuild();

			if (tag.equals(core.activeTag()))
			{
				core.resetBank();
			}

			say("Tag tab '" + tag + "' has been imported from your clipboard!");
		}
		catch (UnsupportedFlavorException | NoSuchElementException | IOException | NumberFormatException e)
		{
			log.debug("failed to import tab", e);
			say("Failed to import tag tab from clipboard, invalid format.");
		}
	}

	/** The core plugin's own export format. */
	private String importBankTags(Iterator<String> data)
	{
		String name = data.next();
		if ("banktags".equals(name))
		{
			data.next(); // version
			name = data.next();
		}

		name = filterName(name);
		if (name == null)
		{
			return null;
		}

		core.setIcon(name, Integer.parseInt(data.next()));

		while (data.hasNext())
		{
			String token = data.next();
			if ("layout".equals(token))
			{
				break;
			}
			int itemId = Integer.parseInt(token);
			// A negative id is core's marker for "tag every variant".
			core.tagItem(itemId, name, itemId < 0);
		}

		if (data.hasNext())
		{
			Layout layout = new Layout(name);
			while (data.hasNext())
			{
				int idx = Integer.parseInt(data.next());
				int itemId = Integer.parseInt(data.next());
				layout.setItemAtPos(itemId, idx);
				core.tagItem(itemId, name, false);
			}
			core.saveLayout(layout);
		}

		return name;
	}

	/** The Bank Tag Layouts plugin's format, which core also accepts. */
	private String importBankTagLayouts(Iterator<String> data)
	{
		String header = data.next();
		String name = filterName(header.substring("banktaglayoutsplugin:".length()));
		if (name == null)
		{
			return null;
		}

		Layout layout = new Layout(name);

		while (data.hasNext())
		{
			String token = data.next();
			if (token.startsWith("banktag:"))
			{
				break;
			}
			String[] parts = token.split(":");
			layout.setItemAtPos(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
		}

		core.setIcon(name, Integer.parseInt(data.next()));

		while (data.hasNext())
		{
			int itemId = Integer.parseInt(data.next());
			core.tagItem(itemId, name, itemId < 0);
		}

		core.saveLayout(layout);
		return name;
	}

	private String filterName(String name)
	{
		StringBuilder sb = new StringBuilder();
		for (char c : name.toCharArray())
		{
			if (TabInterface.FILTERED_CHARS.test(c))
			{
				sb.append(c);
			}
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------

	private void promptName(String prompt, Consumer<String> onDone)
	{
		chatboxPanelManager.openTextInput(prompt)
			.addCharValidator(TabInterface.FILTERED_CHARS)
			.onDone((Consumer<String>) value ->
			{
				String name = value.trim();
				if (!name.isEmpty())
				{
					// Chatbox input is driven from key events, so the callback is
					// not guaranteed to be on the client thread -- and every one
					// of these handlers goes on to rebuild widgets.
					clientThread.invoke(() -> onDone.accept(name));
				}
			})
			.build();
	}

	/**
	 * The potion store is a bank tab on the server, not just a client view, so
	 * moving off it client-side would leave deposits going to it. We cannot
	 * close it without sending an action, so we decline instead.
	 */
	boolean isPotionStoreOpen()
	{
		return client.getVarbitValue(VarbitID.BANK_CURRENTTAB) == BANKTAB_POTIONSTORE;
	}

	void sayPotionStoreIsOpen()
	{
		say("Close the potion store before opening a tag tab.");
	}

	private void say(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}
}

package com.banktagfolders;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The folder structure laid over the core plugin's flat tag list, plus its
 * persistence.
 * <p>
 * The core tag list stays the single source of truth for which tags exist; this
 * class only records how they are <em>grouped</em>. That split is what makes the
 * plugin non-destructive: every mutation here writes to
 * {@value #GROUP}, never to {@code banktags}.
 */
@Slf4j
@Singleton
public class FolderTree
{
	static final String GROUP = "banktagfolders";

	static final String KEY_FOLDERS = "folders";
	static final String KEY_ROOTS = "roots";

	/** Root entries are tagged so a folder id can never be read as a tag name. */
	private static final String TAG = "t:";
	private static final String FOLDER = "f:";

	/**
	 * Default folder colours, mid-dark so the game's white and orange text stays
	 * readable on top. A new folder takes the first one not already in use.
	 */
	private static final int[] PALETTE = {
		0x3A6B8B, 0x4A7A4A, 0x8B3A3A, 0x6B4A8B,
		0x8B7A3A, 0x3A8B7A, 0x8B5A3A, 0x7A3A6B,
	};

	private final ConfigManager configManager;

	/**
	 * The client's Gson, injected rather than constructed. Building a fresh
	 * instance is rejected by the Plugin Hub, and it would also mean this
	 * plugin quietly stops matching the client's own serialisation settings if
	 * those ever change.
	 * <p>
	 * Everything is read and written as a concrete array type rather than via
	 * Gson's {@code TypeToken}. TypeToken resolves a generic type at runtime
	 * through {@code java.lang.reflect.Type}, and the Plugin Hub does not permit
	 * reflection; an array carries its element type in the class itself.
	 */
	private final Gson gson;

	/** Folder id to folder, insertion ordered so saves round-trip stably. */
	private final Map<String, Folder> folders = new LinkedHashMap<>();

	/** Top level in display order; each entry is {@code t:<tag>} or {@code f:<id>}. */
	private final List<String> roots = new ArrayList<>();

	@Inject
	FolderTree(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	// ------------------------------------------------------------------
	// Persistence
	// ------------------------------------------------------------------

	void load()
	{
		folders.clear();
		roots.clear();

		Folder[] stored = read(KEY_FOLDERS, Folder[].class);
		if (stored != null)
		{
			for (Folder folder : stored)
			{
				// A null id would make the folder unaddressable and every row
				// pointing at it dead, so drop it rather than render a ghost.
				if (folder != null && folder.getId() != null)
				{
					if (folder.getTags() == null)
					{
						folder.setTags(new ArrayList<>());
					}
					if (folder.getColor() == 0)
					{
						folder.setColor(nextColor());
					}
					folders.put(folder.getId(), folder);
				}
			}
		}

		String[] storedRoots = read(KEY_ROOTS, String[].class);
		if (storedRoots != null)
		{
			Collections.addAll(roots, storedRoots);
		}
	}

	@Nullable
	private <T> T read(String key, Class<T> type)
	{
		String json = configManager.getConfiguration(GROUP, key);
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, type);
		}
		catch (JsonSyntaxException e)
		{
			// Better to start from an empty structure than to refuse to render
			// the column at all; reconcile() will rebuild it from the live tags.
			log.warn("Discarding unreadable {}.{}", GROUP, key, e);
			return null;
		}
	}

	void save()
	{
		configManager.setConfiguration(GROUP, KEY_FOLDERS, gson.toJson(folders.values().toArray(new Folder[0])));
		configManager.setConfiguration(GROUP, KEY_ROOTS, gson.toJson(roots.toArray(new String[0])));
	}

	// ------------------------------------------------------------------
	// Reconciliation against the core tag list
	// ------------------------------------------------------------------

	/**
	 * Fold the live tag list into the stored structure.
	 * <p>
	 * Runs before every render, because tags can appear and disappear entirely
	 * outside this plugin -- created from the core plugin's own UI, deleted,
	 * renamed, or imported. Anything unknown is adopted at the end of the
	 * column and anything stale is dropped, so the two never drift apart.
	 *
	 * @param liveTags tag names in the order {@code banktags} lists them
	 */
	void reconcile(List<String> liveTags)
	{
		Set<String> live = new LinkedHashSet<>(liveTags);
		boolean dirty = false;

		for (Folder folder : new ArrayList<>(folders.values()))
		{
			boolean lostTags = folder.getTags().retainAll(live);
			if (lostTags)
			{
				dirty = true;
			}

			// "Remove all from a folder to remove the folder", covering the case
			// where the last member was deleted from the bank rather than
			// dragged out. Conditioned on having actually lost something this
			// pass: an empty folder that did not just lose its last tag is a
			// brand new one waiting to be filled, and deleting it here would
			// make "New folder" appear to do nothing.
			if (lostTags && folder.getTags().isEmpty())
			{
				folders.remove(folder.getId());
				dirty = true;
			}
		}

		Set<String> filed = new HashSet<>();
		for (Folder folder : folders.values())
		{
			filed.addAll(folder.getTags());
		}

		Set<String> seen = new HashSet<>();
		for (Iterator<String> it = roots.iterator(); it.hasNext(); )
		{
			String entry = it.next();
			if (!seen.add(entry) || !isLiveRoot(entry, live, filed))
			{
				it.remove();
				dirty = true;
			}
		}

		// Folders and tags the roots list has never seen join the bottom of the
		// column, tags in the order the bank itself lists them.
		for (Folder folder : folders.values())
		{
			if (!roots.contains(FOLDER + folder.getId()))
			{
				roots.add(FOLDER + folder.getId());
				dirty = true;
			}
		}
		for (String tag : liveTags)
		{
			if (!filed.contains(tag) && !roots.contains(TAG + tag))
			{
				roots.add(TAG + tag);
				dirty = true;
			}
		}

		if (dirty)
		{
			save();
		}
	}

	private boolean isLiveRoot(String entry, Set<String> live, Set<String> filed)
	{
		if (entry.startsWith(FOLDER))
		{
			return folders.containsKey(entry.substring(FOLDER.length()));
		}
		if (entry.startsWith(TAG))
		{
			String tag = entry.substring(TAG.length());
			// A tag that has since been filed into a folder must not also keep
			// its top-level slot, or it renders twice.
			return live.contains(tag) && !filed.contains(tag);
		}
		return false;
	}

	// ------------------------------------------------------------------
	// Display
	// ------------------------------------------------------------------

	/** The column, flattened: folder headers with their members under them. */
	List<StripRow> rows()
	{
		List<StripRow> rows = new ArrayList<>();
		for (String entry : roots)
		{
			if (entry.startsWith(TAG))
			{
				rows.add(StripRow.tag(entry.substring(TAG.length()), null));
				continue;
			}

			Folder folder = folders.get(entry.substring(FOLDER.length()));
			if (folder == null)
			{
				continue;
			}

			rows.add(StripRow.folder(folder));
			if (!folder.isCollapsed())
			{
				for (String tag : folder.getTags())
				{
					rows.add(StripRow.tag(tag, folder));
				}
			}
		}
		return rows;
	}

	@Nullable
	Folder folder(String id)
	{
		return folders.get(id);
	}

	@Nullable
	Folder folderOf(String tag)
	{
		for (Folder folder : folders.values())
		{
			if (folder.getTags().contains(tag))
			{
				return folder;
			}
		}
		return null;
	}

	// ------------------------------------------------------------------
	// Mutations
	// ------------------------------------------------------------------

	/**
	 * Drag one tab onto another: the phone-homescreen gesture that makes a
	 * folder. The new folder takes the slot the target tab was occupying, so it
	 * appears exactly where the player dropped it.
	 */
	Folder createFolder(String name, String target, String dragged)
	{
		Folder folder = new Folder();
		folder.setId(newId());
		folder.setName(name);
		folder.setColor(nextColor());
		folder.getTags().add(target);
		folder.getTags().add(dragged);

		// Detach the dragged tag first, then re-read the target's index: taking
		// the index up front and detaching afterwards drops the folder a slot
		// too high whenever the dragged tab sat above its target.
		detach(dragged);
		int at = roots.indexOf(TAG + target);
		detach(target);

		folders.put(folder.getId(), folder);
		roots.add(at < 0 || at > roots.size() ? roots.size() : at, FOLDER + folder.getId());
		save();
		return folder;
	}

	/** An empty folder, added at the bottom, for filling by drag afterwards. */
	Folder createEmptyFolder(String name)
	{
		Folder folder = new Folder();
		folder.setId(newId());
		folder.setName(name);
		folder.setColor(nextColor());
		folders.put(folder.getId(), folder);
		roots.add(FOLDER + folder.getId());
		save();
		return folder;
	}

	/**
	 * Follow a tag through a rename, keeping its slot.
	 * <p>
	 * Without this, {@link #reconcile} would see the old name vanish and the new
	 * one appear, and quietly drop a renamed tab out of its folder to the bottom
	 * of the column.
	 */
	void renameTag(String from, String to)
	{
		int at = roots.indexOf(TAG + from);
		if (at >= 0)
		{
			roots.set(at, TAG + to);
		}

		for (Folder folder : folders.values())
		{
			int index = folder.getTags().indexOf(from);
			if (index >= 0)
			{
				folder.getTags().set(index, to);
			}
		}
		save();
	}

	/**
	 * The top-level slot a row occupies.
	 * <p>
	 * A tag inside a folder resolves to the folder's slot, so dropping next to
	 * a nested tab means "next to its folder" rather than nothing at all.
	 */
	private int rootSlotOf(StripRow target)
	{
		if (target.isFolder())
		{
			return roots.indexOf(FOLDER + target.getFolder().getId());
		}

		Folder parent = target.getParent();
		if (parent != null)
		{
			return roots.indexOf(FOLDER + parent.getId());
		}
		return roots.indexOf(TAG + target.getTag());
	}

	/** Drop a tag at the top level, immediately before or after a row. */
	void moveTagNear(String tag, StripRow target, boolean after)
	{
		detach(tag);

		// Resolved after detaching: removing the tag can shift every slot below
		// it, and can delete a folder it just emptied.
		int at = rootSlotOf(target);
		roots.add(at < 0 ? roots.size() : (after ? Math.min(at + 1, roots.size()) : at), TAG + tag);
		save();
	}

	/** Move a whole folder before or after a row. */
	void moveFolderNear(String folderId, StripRow target, boolean after)
	{
		String key = FOLDER + folderId;
		if (!roots.remove(key))
		{
			return;
		}

		int at = rootSlotOf(target);
		roots.add(at < 0 ? roots.size() : (after ? Math.min(at + 1, roots.size()) : at), key);
		save();
	}

	/** Drop a tag inside a folder, beside one of its existing members. */
	void moveTagIntoFolderNear(String tag, String folderId, String targetTag, boolean after)
	{
		detach(tag);

		Folder folder = folders.get(folderId);
		if (folder == null)
		{
			// detach() deletes a folder it just emptied, so the destination can
			// vanish underneath us when the tag was its only member.
			return;
		}

		List<String> tags = folder.getTags();
		int at = tags.indexOf(targetTag);
		tags.add(at < 0 ? tags.size() : (after ? Math.min(at + 1, tags.size()) : at), tag);
		save();
	}

	/** Nudge a top-level entry one slot up or down. */
	void moveRoot(String entry, int delta)
	{
		int from = roots.indexOf(entry);
		if (from < 0)
		{
			return;
		}

		int to = from + delta;
		if (to < 0 || to >= roots.size())
		{
			return;
		}

		roots.remove(from);
		roots.add(to, entry);
		save();
	}

	/** Nudge a tag one slot up or down within the folder holding it. */
	void moveWithinFolder(String tag, String folderId, int delta)
	{
		Folder folder = folders.get(folderId);
		if (folder == null)
		{
			return;
		}

		List<String> tags = folder.getTags();
		int from = tags.indexOf(tag);
		int to = from + delta;
		if (from < 0 || to < 0 || to >= tags.size())
		{
			return;
		}

		tags.remove(from);
		tags.add(to, tag);
		save();
	}

	/** Drop a tag into a folder, at {@code index} among its members, or last. */
	void moveIntoFolder(String tag, String folderId, int index)
	{
		Folder folder = folders.get(folderId);
		if (folder == null)
		{
			return;
		}

		detach(tag);

		// detach() deletes a folder it just emptied, so the destination may have
		// vanished underneath us when the tag was that folder's only member.
		if (!folders.containsKey(folderId))
		{
			return;
		}

		List<String> tags = folder.getTags();
		tags.add(index < 0 || index > tags.size() ? tags.size() : index, tag);
		save();
	}

	/** Drag a tag back out to the top level, landing at {@code index}. */
	void moveToRoot(String tag, int index)
	{
		detach(tag);
		roots.add(index < 0 || index > roots.size() ? roots.size() : index, TAG + tag);
		save();
	}

	/** Reorder a top-level entry (a loose tag, or a whole folder). */
	void reorderRoot(String entry, int index)
	{
		int from = roots.indexOf(entry);
		if (from < 0)
		{
			return;
		}
		roots.remove(from);
		roots.add(index < 0 || index > roots.size() ? roots.size() : index, entry);
		save();
	}

	/**
	 * Open whatever folder a tag is hiding in.
	 * <p>
	 * Used when the bank reopens on a remembered tag: leaving it inside a
	 * collapsed folder would show the tag's contents with nothing in the column
	 * marked active, which reads as a bug.
	 */
	void reveal(String tag)
	{
		Folder folder = folderOf(tag);
		if (folder != null && folder.isCollapsed())
		{
			folder.setCollapsed(false);
			save();
		}
	}

	/** The first palette colour no folder is using, else one by position. */
	private int nextColor()
	{
		for (int candidate : PALETTE)
		{
			boolean taken = false;
			for (Folder folder : folders.values())
			{
				if (folder.getColor() == candidate)
				{
					taken = true;
					break;
				}
			}
			if (!taken)
			{
				return candidate;
			}
		}
		return PALETTE[folders.size() % PALETTE.length];
	}

	void setColor(String folderId, int rgb)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setColor(rgb);
			save();
		}
	}

	void toggleCollapsed(String folderId)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setCollapsed(!folder.isCollapsed());
			save();
		}
	}

	void rename(String folderId, String name)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setName(name);
			save();
		}
	}

	void setIcon(String folderId, int itemId)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setIconItemId(itemId);
			save();
		}
	}

	/** Delete a folder, spilling its tags back out where it stood. */
	void dissolve(String folderId)
	{
		Folder folder = folders.remove(folderId);
		if (folder == null)
		{
			return;
		}

		int at = roots.indexOf(FOLDER + folderId);
		if (at < 0)
		{
			at = roots.size();
		}
		else
		{
			roots.remove(at);
		}

		for (String tag : folder.getTags())
		{
			roots.add(at++, TAG + tag);
		}
		save();
	}

	/** Root index of a row, for working out where a drop should land. */
	int rootIndexOf(StripRow row)
	{
		if (row.isFolder())
		{
			return roots.indexOf(FOLDER + row.getFolder().getId());
		}
		return roots.indexOf(TAG + row.getTag());
	}

	String rootKey(StripRow row)
	{
		return row.isFolder() ? FOLDER + row.getFolder().getId() : TAG + row.getTag();
	}

	/**
	 * Unlink a tag from wherever it currently sits.
	 * <p>
	 * Not saved on its own: every caller goes on to re-file the tag and saves
	 * once, so a half-applied move never reaches disk.
	 */
	private void detach(String tag)
	{
		roots.remove(TAG + tag);

		for (Folder folder : new ArrayList<>(folders.values()))
		{
			if (folder.getTags().remove(tag) && folder.getTags().isEmpty())
			{
				folders.remove(folder.getId());
				roots.remove(FOLDER + folder.getId());
			}
		}
	}

	private String newId()
	{
		String id;
		do
		{
			id = Long.toHexString(ThreadLocalRandom.current().nextLong() & 0xFFFFFFFFFFFFL);
		}
		while (folders.containsKey(id));
		return id;
	}
}

package com.banktagfolders;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.FontID;
import net.runelite.api.Point;
import net.runelite.api.ScriptEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfig;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.tabs.TabSprites;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;

/**
 * The tag column: a faithful rebuild of the core plugin's tab strip, with
 * folders layered on top.
 * <p>
 * The widget model is copied from {@code TabInterface} because it has to be.
 * The strip lives in the <em>dynamic</em> children of
 * {@code Bankmain.ITEMS_CONTAINER}: a handful of persistent widgets first (the
 * scroll catcher, the two arrows and the new-tab button), then the rows after
 * them. Rows are created once per bank rebuild and only <em>repositioned</em>
 * when scrolling, which is why scrolling stays cheap.
 * <p>
 * Rows are packed against a pixel budget rather than counted against a fixed tab
 * height as core does, so a row is free to be a different size without the
 * scrolling arithmetic caring.
 */
@Slf4j
@Singleton
public class TagColumn
{
	private static final java.awt.Color HILIGHT_COLOR = JagexColors.MENU_TARGET;

	static final String SCROLL_UP = "Scroll up";
	static final String SCROLL_DOWN = "Scroll down";

	private static final int TAB_WIDTH = 39;
	private static final int MARGIN = 1;
	private static final int BUTTON_HEIGHT = 20;
	private static final int NEW_TAB_HEIGHT = 39;
	/** Offset from the bottom of the bank container, as core measures it. */
	private static final int BANK_BOTTOM_OFFSET = 39;
	/** Rate limit for hold-to-scroll on the arrow buttons, in milliseconds. */
	private static final int SCROLL_TICK = 500;

	/** Ops, numbered as core numbers them: registered at index, read as index+1. */
	static final int TAB_OP_OPEN_TAG = 1;
	static final int TAB_OP_CHANGE_ICON = 2;
	static final int TAB_OP_LAYOUT = 3;
	static final int TAB_OP_EXPORT_TAB = 4;
	static final int TAB_OP_RENAME_TAB = 5;
	static final int TAB_OP_DELETE_TAB = 6;
	/** Ours, and only present on a tag that is actually inside a folder. */
	static final int TAB_OP_UNFILE = 7;

	static final int FOLDER_OP_TOGGLE = 1;
	static final int FOLDER_OP_CHANGE_ICON = 2;
	static final int FOLDER_OP_SET_COLOUR = 3;
	static final int FOLDER_OP_RENAME = 4;
	static final int FOLDER_OP_DELETE = 5;

	static final int NEWTAB_OP_NEW_TAB = 1;
	static final int NEWTAB_OP_IMPORT_TAB = 2;
	static final int NEWTAB_OP_OPEN_TAB_MENU = 3;
	static final int NEWTAB_OP_NEW_FOLDER = 4;

	private static final int FOLDER_TEXT = 0xFFFFFF;

	private final Client client;
	private final BankTagFoldersConfig config;
	private final FolderTree tree;
	private final CoreBankTags core;

	/**
	 * Lazily resolved to break the injection cycle: the actions need to ask for
	 * a redraw when they finish, and the column needs to hand them clicks.
	 */
	private final Provider<ColumnActions> actions;

	private Widget parent;
	private Widget scrollComponent;
	private Widget upButton;
	private Widget downButton;
	private Widget newTab;

	@Getter
	private boolean initialised;

	/**
	 * How many dynamic children the bank container already had before we added
	 * ours. Core assumes zero; measuring instead means a stray child from
	 * elsewhere is left alone rather than deleted.
	 */
	private int baseChildCount;

	private int scrollRow;
	private int availableHeight;
	private Instant startScroll = Instant.now();

	private List<StripRow> rows = new ArrayList<>();
	private final List<RenderedRow> rendered = new ArrayList<>();
	private final Map<Widget, StripRow> rowByWidget = new IdentityHashMap<>();

	/**
	 * The icons we appended to the bank's item list for the tag-tab overview.
	 * <p>
	 * Held by reference rather than by index. The bank's own item widgets live
	 * in the same container, and an index remembered from one bank state is a
	 * licence to hide somebody else's widgets in the next.
	 */
	private final List<Widget> overviewIcons = new ArrayList<>();

	/**
	 * A tag to open the folder of and scroll to on the next rebuild.
	 * <p>
	 * Deferred because the request arrives as the bank initialises, well before
	 * there are any rows to scroll among.
	 */
	@Nullable
	private String pendingReveal;

	@Inject
	TagColumn(Client client, BankTagFoldersConfig config, FolderTree tree, CoreBankTags core,
		Provider<ColumnActions> actions)
	{
		this.client = client;
		this.config = config;
		this.tree = tree;
		this.core = core;
		this.actions = actions;
	}

	/** One widget belonging to a row, and its offset below the row's top. */
	private static class Piece
	{
		private final Widget widget;
		private final int dy;

		Piece(Widget widget, int dy)
		{
			this.widget = widget;
			this.dy = dy;
		}
	}

	/** A row's widgets, created once per rebuild and repositioned on scroll. */
	private static class RenderedRow
	{
		private final StripRow row;
		private final int height;
		private final List<Piece> pieces = new ArrayList<>();

		/** Where the row last landed, or -1 while it is scrolled out of view. */
		private int top = -1;

		RenderedRow(StripRow row, int height)
		{
			this.row = row;
			this.height = height;
		}
	}

	/** Where a drop landed relative to the row under the cursor. */
	enum DropZone
	{
		BEFORE,
		INTO,
		AFTER
	}

	/**
	 * A resolved drop: the row under the cursor and which part of it was hit.
	 * <p>
	 * The distinction is what lets one gesture do two jobs. Dropping into the
	 * middle of a tab groups the two into a folder, the way phone home screens
	 * do; dropping near an edge inserts between rows instead. Without it,
	 * "drag one tab onto another" would have to mean either grouping or
	 * reordering, and the other would need a menu.
	 */
	static class Drop
	{
		private final StripRow row;
		private final DropZone zone;

		Drop(StripRow row, DropZone zone)
		{
			this.row = row;
			this.zone = zone;
		}

		StripRow getRow()
		{
			return row;
		}

		DropZone getZone()
		{
			return zone;
		}
	}

	// ------------------------------------------------------------------
	// Lifecycle
	// ------------------------------------------------------------------

	void init()
	{
		if (initialised)
		{
			return;
		}

		parent = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (parent == null)
		{
			return;
		}

		Widget[] existing = parent.getChildren();
		baseChildCount = existing == null ? 0 : existing.length;

		int width = TAB_WIDTH;

		// Not really a text widget -- it exists only to catch the scroll wheel
		// over the column, exactly as core's does.
		scrollComponent = parent.createChild(-1, WidgetType.TEXT);
		scrollComponent.setHasListener(true);
		scrollComponent.setNoScrollThrough(true);
		scrollComponent.setOnScrollWheelListener((JavaScriptCallback) event -> scrollBy(event.getMouseY()));

		upButton = createGraphic("", TabSprites.UP_ARROW.getSpriteId(), -1, width, BUTTON_HEIGHT, MARGIN, 0);
		upButton.setAction(1, SCROLL_UP);
		upButton.setClickMask(upButton.getClickMask() | WidgetConfig.DRAG_ON);
		upButton.setHasListener(true);
		upButton.setOnOpListener((JavaScriptCallback) event -> scrollBy(-1));

		downButton = createGraphic("", TabSprites.DOWN_ARROW.getSpriteId(), -1, width, BUTTON_HEIGHT, MARGIN, 0);
		downButton.setAction(1, SCROLL_DOWN);
		downButton.setClickMask(downButton.getClickMask() | WidgetConfig.DRAG_ON);
		downButton.setHasListener(true);
		downButton.setOnOpListener((JavaScriptCallback) event -> scrollBy(1));

		newTab = createGraphic("", TabSprites.NEW_TAB.getSpriteId(), -1, width, NEW_TAB_HEIGHT, MARGIN, 0);
		newTab.setHasListener(true);
		newTab.setAction(NEWTAB_OP_NEW_TAB, "New tag tab");
		newTab.setAction(NEWTAB_OP_IMPORT_TAB, "Import tag tab");
		newTab.setAction(NEWTAB_OP_OPEN_TAB_MENU, "View tag tabs");
		newTab.setAction(NEWTAB_OP_NEW_FOLDER, "New folder");
		newTab.setOnOpListener((JavaScriptCallback) event -> actions.get().onNewTabOp(event.getOp() - 1));

		tree.load();
		initialised = true;
	}

	/**
	 * Whether the widgets in the container are still the ones we put there.
	 * <p>
	 * The core strip's {@code deinit()} calls {@code deleteAllChildren()} on the
	 * same container, so toggling its setting -- or any other plugin rebuilding
	 * the bank -- can pull our widgets out from under us while we still think we
	 * are set up. Verified by identity rather than by counting, because a count
	 * can match by coincidence.
	 */
	private boolean ownsWidgets()
	{
		if (parent == null || scrollComponent == null || parent != client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER))
		{
			return false;
		}

		Widget[] children = parent.getChildren();
		return children != null
			&& children.length > baseChildCount
			&& children[baseChildCount] == scrollComponent;
	}

	void deinit()
	{
		// Only cut back what is still ours. Truncating a container something
		// else has since rebuilt would delete that plugin's widgets instead.
		if (parent != null && ownsWidgets())
		{
			truncateChildren(baseChildCount);
		}

		parent = scrollComponent = upButton = downButton = newTab = null;
		initialised = false;
		rendered.clear();
		rowByWidget.clear();
		rows = new ArrayList<>();
		scrollRow = 0;
		// Not hidden first: the bank is closing and will rebuild these widgets
		// itself, and they may already be gone.
		overviewIcons.clear();
		pendingReveal = null;
	}

	/** Cut our widgets back off, leaving anything that was there before us. */
	private void truncateChildren(int keep)
	{
		Widget[] children = parent.getChildren();
		if (children == null)
		{
			return;
		}
		if (keep <= 0)
		{
			parent.deleteAllChildren();
			return;
		}
		if (children.length > keep)
		{
			parent.setChildren(Arrays.copyOf(children, keep));
		}
	}

	// ------------------------------------------------------------------
	// Building
	// ------------------------------------------------------------------

	/**
	 * Rebuild everything.
	 * <p>
	 * Wrapped end to end: a layout mistake should cost the player their tag
	 * column for a frame, never their bank.
	 */
	void rebuild()
	{
		try
		{
			// Our widgets can be destroyed underneath us -- the core strip's
			// deinit deletes every child of this container. Rebuilding onto
			// dead references is what makes toggling either plugin leave a
			// half-drawn column behind, so start over instead.
			if (initialised && !ownsWidgets())
			{
				deinit();
			}

			if (!initialised)
			{
				init();
			}
			if (!initialised)
			{
				return;
			}
			repositionButtons();
			rebuildRows();
		}
		catch (Exception e)
		{
			log.warn("Tag column rebuild failed; leaving the bank alone", e);
		}
	}

	/**
	 * Reposition without rebuilding.
	 * <p>
	 * Used for bank resizes and the storage popup, where the rows themselves are
	 * unchanged and only the space they have has moved.
	 */
	void relayout()
	{
		try
		{
			if (initialised)
			{
				repositionButtons();
				layoutRows();
			}
		}
		catch (Exception e)
		{
			log.warn("Tag column relayout failed", e);
		}
	}

	/**
	 * Position the fixed furniture and work out how much height the rows get.
	 * <p>
	 * Ported from core's {@code repositionButtons}, including the clamping
	 * against the incinerator, the collapse button and the storage popup tab --
	 * without which the column runs underneath them.
	 */
	private void repositionButtons()
	{
		int height = parent.getHeight() - BANK_BOTTOM_OFFSET;

		Widget widget = client.getWidget(InterfaceID.Bankmain.INCINERATOR_TARGET);
		if (widget != null && !widget.isHidden())
		{
			height = Math.min(height, widget.getRelativeY());
		}

		widget = client.getWidget(InterfaceID.Bankmain.POPUP_BUTTON_OUT);
		if (widget != null && !widget.isHidden())
		{
			height = Math.min(height, widget.getRelativeY());
		}

		Widget popupTab = client.getWidget(InterfaceID.Bankmain.STORAGE_POPUP_TAB);
		if (popupTab != null && !popupTab.isHidden())
		{
			widget = client.getWidget(InterfaceID.Bankmain.GIM_STORAGE);
			if (widget != null && !widget.isHidden())
			{
				height = Math.min(height, popupTab.getRelativeY() + widget.getRelativeY());
			}

			widget = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_BUTTON);
			if (widget != null && !widget.isHidden())
			{
				height = Math.min(height, popupTab.getRelativeY() + widget.getRelativeY());
			}
		}

		int width = TAB_WIDTH;

		newTab.setOriginalWidth(width);
		newTab.revalidate();

		scrollComponent.setOriginalY(NEW_TAB_HEIGHT + 2 + BUTTON_HEIGHT);
		scrollComponent.setOriginalWidth(width + MARGIN * 2);

		availableHeight = Math.max(0, height - scrollComponent.getOriginalY() - BUTTON_HEIGHT);
		scrollComponent.setOriginalHeight(availableHeight);
		scrollComponent.revalidate();

		upButton.setOriginalY(NEW_TAB_HEIGHT + 2);
		upButton.setOriginalWidth(width);
		upButton.revalidate();

		downButton.setOriginalY(scrollComponent.getOriginalY() + availableHeight + MARGIN);
		downButton.setOriginalWidth(width);
		downButton.revalidate();
	}

	private void rebuildRows()
	{
		truncateChildren(baseChildCount + 4);
		rendered.clear();
		rowByWidget.clear();

		// Before anything is drawn: other plugins ask the core TabManager what
		// tabs exist, and with the core strip off nothing else fills it in.
		core.syncTabManager();

		tree.reconcile(core.tagTabs());
		if (pendingReveal != null)
		{
			// Expanded before the rows are flattened, so the tag is actually
			// among them and can be scrolled to below.
			tree.reveal(pendingReveal);
		}
		rows = tree.rows();

		int width = TAB_WIDTH;
		for (StripRow row : rows)
		{
			rendered.add(row.isFolder() ? buildFolderRow(row, width) : buildTagRow(row, width));
		}

		layoutRows();

		if (pendingReveal != null)
		{
			scrollToTag(pendingReveal);
			pendingReveal = null;
		}
	}

	private RenderedRow buildTagRow(StripRow row, int width)
	{
		String tag = row.getTag();
		int height = rowHeight();
		String name = ColorUtil.wrapWithColorTag(tag, HILIGHT_COLOR);
		boolean active = tag.equals(core.activeTag());

		RenderedRow out = new RenderedRow(row, height);

		Widget background = createGraphic(name,
			(active ? TabSprites.TAB_BACKGROUND_ACTIVE : TabSprites.TAB_BACKGROUND).getSpriteId(),
			-1, width, height, MARGIN, -1);
		background.setSpriteTiling(true);
		addTabActions(row, background);
		addDragOptions(background);
		out.pieces.add(new Piece(background, 0));
		rowByWidget.put(background, row);

		// Membership is shown by colour rather than by indenting the row. An
		// indent deep enough to read also pushed the 36px item sprite off the
		// right of a 39px column.
		if (row.isNested())
		{
			// Lighter over the active tab, which would otherwise stop looking
			// active once it is tinted.
			int opacity = Math.min(255, opacityOf(config.tagTintStrength()) + (active ? 60 : 0));
			out.pieces.add(new Piece(
				fill(row.getParent().getColor(), opacity, MARGIN, width, height), 0));
		}

		int iconDy = Math.max(0, (height - Constants.ITEM_SPRITE_HEIGHT) / 2);
		// Only the background carries the menu options. The icon sits on top of
		// it and the two overlap, so giving both the same options makes the
		// client collect every entry twice. Clicks land on the background
		// underneath, which is how the stock strip does it too.
		Widget icon = createGraphic(name, -1, core.iconFor(tag),
			Constants.ITEM_SPRITE_WIDTH, Constants.ITEM_SPRITE_HEIGHT, MARGIN + 3, -1);
		addDragOptions(icon);
		out.pieces.add(new Piece(icon, iconDy));
		rowByWidget.put(icon, row);

		// No name is drawn: the game already announces it in the hover text at
		// the top left ("View tag tab potions"), and a text widget does not clip
		// to its own bounds, so anything longer than the column ran over the
		// bank items.
		return out;
	}

	private RenderedRow buildFolderRow(StripRow row, int width)
	{
		Folder folder = row.getFolder();
		int height = rowHeight();
		String name = ColorUtil.wrapWithColorTag(folder.getName(), HILIGHT_COLOR);

		RenderedRow out = new RenderedRow(row, height);

		Widget background = fill(folder.getColor(), opacityOf(config.folderTintStrength()), MARGIN, width, height);
		background.setName(name);
		background.setAction(FOLDER_OP_TOGGLE, folder.isCollapsed() ? "Expand" : "Collapse");
		background.setAction(FOLDER_OP_CHANGE_ICON, "Change icon");
		background.setAction(FOLDER_OP_SET_COLOUR, "Set colour");
		background.setAction(FOLDER_OP_RENAME, "Rename folder");
		background.setAction(FOLDER_OP_DELETE, "Delete folder");
		background.setHasListener(true);
		background.setOnOpListener((JavaScriptCallback) event ->
			actions.get().onFolderOp(event.getOp() - 1, row));
		addDragOptions(background);
		out.pieces.add(new Piece(background, 0));
		rowByWidget.put(background, row);

		// Item sprites are transparent around the item, so the folder's colour
		// still reads through from the rectangle behind. Drawn at its native
		// size: scaling one down is a nearest-neighbour resample and looks
		// visibly broken.
		int icon = folderIcon(folder);
		if (icon > 0)
		{
			Widget item = createGraphic(name, -1, icon,
				Constants.ITEM_SPRITE_WIDTH, Constants.ITEM_SPRITE_HEIGHT, MARGIN + 3, -1);
			out.pieces.add(new Piece(item, (height - Constants.ITEM_SPRITE_HEIGHT) / 2));
		}

		// A plain "+"/"-" rather than a chevron: the game fonts do not carry the
		// arrow codepoints, and a missing glyph reads as an empty row. Badged
		// into the corner when there is an icon under it.
		Widget marker = parent.createChild(-1, WidgetType.TEXT);
		marker.setText(folder.isCollapsed() ? "+" : "-");
		marker.setFontId(FontID.BOLD_12);
		marker.setTextColor(FOLDER_TEXT);
		marker.setTextShadowed(true);
		marker.setOriginalX(MARGIN + 2);
		marker.setOriginalY(-1);
		marker.setOriginalWidth(10);
		marker.setOriginalHeight(icon > 0 ? 12 : height);
		marker.setXTextAlignment(WidgetTextAlignment.LEFT);
		marker.setYTextAlignment(WidgetTextAlignment.CENTER);
		marker.revalidate();
		out.pieces.add(new Piece(marker, 0));

		return out;
	}

	/**
	 * A folder with no icon of its own borrows its first member's, so a folder
	 * made by dragging two tabs together is never a blank bar.
	 */
	private int folderIcon(Folder folder)
	{
		if (folder.getIconItemId() > 0)
		{
			return folder.getIconItemId();
		}
		return folder.getTags().isEmpty() ? 0 : core.iconFor(folder.getTags().get(0));
	}

	private void addTabActions(StripRow row, Widget w)
	{
		w.setAction(TAB_OP_OPEN_TAG, "View tag tab");
		w.setAction(TAB_OP_CHANGE_ICON, "Change icon");
		w.setAction(TAB_OP_LAYOUT, core.hasLayout(row.getTag()) ? "Disable layout" : "Enable layout");
		w.setAction(TAB_OP_EXPORT_TAB, "Export tag tab");
		w.setAction(TAB_OP_RENAME_TAB, "Rename tag tab");
		w.setAction(TAB_OP_DELETE_TAB, "Delete tag tab");
		if (row.isNested())
		{
			w.setAction(TAB_OP_UNFILE, "Remove from folder");
		}
		w.setHasListener(true);
		w.setOnOpListener((JavaScriptCallback) event -> actions.get().onTagOp(event.getOp() - 1, row));
	}

	/**
	 * Make a widget both draggable and a drop target.
	 * <p>
	 * The quantity settings are core's: an item sprite with no quantity drawn
	 * still needs a non-zero quantity to render at all.
	 */
	private void addDragOptions(Widget w)
	{
		w.setClickMask(w.getClickMask() | WidgetConfig.DRAG | WidgetConfig.DRAG_ON);
		w.setDragDeadTime(5);
		w.setDragDeadZone(5);
		w.setItemQuantity(10000);
		w.setItemQuantityMode(ItemQuantityMode.NEVER);
	}

	/** A filled rectangle in the given colour, used for folder and member tint. */
	private Widget fill(int rgb, int opacity, int x, int width, int height)
	{
		Widget w = parent.createChild(-1, WidgetType.RECTANGLE);
		w.setFilled(true);
		w.setTextColor(rgb);
		w.setOpacity(opacity);
		w.setOriginalX(x);
		w.setOriginalY(-1);
		w.setOriginalWidth(width);
		w.setOriginalHeight(height);
		w.revalidate();
		return w;
	}

	/**
	 * Clamped rather than trusted. A value stored while the allowed range was
	 * wider would otherwise keep rendering out of range until someone reopened
	 * the setting.
	 */
	private int rowHeight()
	{
		return Math.max(24, Math.min(BankTagFoldersConfig.MAX_ROW_HEIGHT, config.tagRowHeight()));
	}

	/**
	 * Config gives strength as a percentage of colour; widgets want the
	 * opposite, where 0 is solid and 255 is invisible.
	 */
	private static int opacityOf(int strength)
	{
		int clamped = Math.max(0, Math.min(100, strength));
		return 255 - (clamped * 255 / 100);
	}

	private Widget createGraphic(String name, int spriteId, int itemId, int width, int height, int x, int y)
	{
		Widget widget = parent.createChild(-1, WidgetType.GRAPHIC);
		widget.setOriginalWidth(width);
		widget.setOriginalHeight(height);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setSpriteId(spriteId);

		if (itemId > 0)
		{
			widget.setItemId(itemId);
			widget.setItemQuantity(-1);
			widget.setBorderType(1);
		}

		widget.setName(name);
		widget.revalidate();
		return widget;
	}

	// ------------------------------------------------------------------
	// Layout and scrolling
	// ------------------------------------------------------------------

	/** Position the visible window of rows; everything else is hidden. */
	void layoutRows()
	{
		if (!initialised)
		{
			return;
		}

		Widget dragged = client.getDraggedWidget();
		for (RenderedRow row : rendered)
		{
			row.top = -1;
			for (Piece piece : row.pieces)
			{
				// Hiding the widget being dragged makes it vanish mid-drag when
				// the column re-lays because of a scroll.
				if (piece.widget != dragged)
				{
					piece.widget.setHidden(true);
				}
			}
		}

		clampScroll();

		int y = scrollComponent.getOriginalY() + MARGIN;
		int used = 0;
		for (int i = scrollRow; i < rendered.size(); i++)
		{
			RenderedRow row = rendered.get(i);
			if (used + row.height > availableHeight)
			{
				break;
			}

			row.top = y;
			for (Piece piece : row.pieces)
			{
				piece.widget.setOriginalY(y + piece.dy);
				piece.widget.setHidden(false);
				piece.widget.revalidate();
			}

			y += row.height + MARGIN;
			used += row.height + MARGIN;
		}
	}

	/**
	 * Pull the scroll position back so the column always ends up full.
	 * <p>
	 * Collapsing a folder can shorten the list under the current offset, and
	 * without this the player is left staring at a mostly empty strip with no
	 * obvious way back.
	 */
	private void clampScroll()
	{
		if (scrollRow <= 0)
		{
			scrollRow = 0;
			return;
		}

		int used = 0;
		int first = rendered.size();
		for (int i = rendered.size() - 1; i >= 0; i--)
		{
			int height = rendered.get(i).height;
			if (used + height > availableHeight)
			{
				break;
			}
			used += height + MARGIN;
			first = i;
		}
		scrollRow = Math.min(scrollRow, first);
	}

	/** Ask for a tag to be revealed and scrolled to when the column next builds. */
	void requestReveal(String tag)
	{
		pendingReveal = tag;
	}

	/** Scroll a tag into view, if it did not already land on screen. */
	private void scrollToTag(String tag)
	{
		for (int i = 0; i < rendered.size(); i++)
		{
			RenderedRow row = rendered.get(i);
			if (row.row.isTag() && tag.equals(row.row.getTag()))
			{
				if (row.top < 0)
				{
					scrollRow = i;
					layoutRows();
				}
				return;
			}
		}
	}

	void scrollBy(int delta)
	{
		if (!initialised || delta == 0)
		{
			return;
		}

		int next = scrollRow + delta;
		if (next < 0)
		{
			next = 0;
		}
		if (next >= rendered.size())
		{
			next = Math.max(0, rendered.size() - 1);
		}

		scrollRow = next;
		layoutRows();
	}

	/** Rate-limited scroll, so holding a drag over an arrow does not race. */
	void scrollTick(int direction)
	{
		if (startScroll.until(Instant.now(), ChronoUnit.MILLIS) >= SCROLL_TICK)
		{
			startScroll = Instant.now();
			scrollBy(direction);
		}
	}

	// ------------------------------------------------------------------
	// Tag tab overview ("View tag tabs")
	// ------------------------------------------------------------------

	/**
	 * Draw every tab as an item icon in the bank area.
	 * <p>
	 * Ported from core: the icons are appended to the bank's own item container
	 * rather than given their own layer, because a new layer would mean
	 * recomputing the bank scrollbar.
	 *
	 * @return the height the bank's scroll area should be given
	 */
	int rebuildOverview(boolean overviewActive)
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null)
		{
			return 0;
		}

		// The bank discards and rebuilds its item widgets, which takes ours with
		// them; a stale reference would be hidden or written to at random.
		for (Widget icon : overviewIcons)
		{
			if (icon == null || icon.getParent() != items)
			{
				overviewIcons.clear();
				break;
			}
		}

		// Hide only what we made. The previous approach -- hide every child past
		// a remembered index -- hid *real bank items* whenever that index was
		// captured while the bank was filtered to a tag. The bank computes its
		// scroll height from the items still visible, so it came out at zero and
		// everything below the first screenful became unreachable.
		for (Widget icon : overviewIcons)
		{
			icon.setHidden(true);
		}

		if (!overviewActive)
		{
			return 0;
		}

		int itemX = BankTagsPlugin.BANK_ITEM_START_X;
		int itemY = BankTagsPlugin.BANK_ITEM_START_Y;
		int rowIndex = 0;
		int used = 0;

		for (String tag : core.tagTabs())
		{
			Widget menu;
			if (used < overviewIcons.size())
			{
				menu = overviewIcons.get(used);
			}
			else
			{
				menu = items.createChild(-1, WidgetType.GRAPHIC);
				menu.setOriginalWidth(BankTagsPlugin.BANK_ITEM_WIDTH);
				menu.setOriginalHeight(BankTagsPlugin.BANK_ITEM_HEIGHT);
				overviewIcons.add(menu);
			}
			used++;

			StripRow row = StripRow.tag(tag, tree.folderOf(tag));
			menu.setHidden(false);
			menu.setOriginalX(itemX);
			menu.setOriginalY(itemY);
			menu.setName(ColorUtil.wrapWithColorTag(tag, HILIGHT_COLOR));
			menu.setItemId(core.iconFor(tag));
			menu.setItemQuantity(-1);
			menu.setBorderType(1);
			addTabActions(row, menu);
			addDragOptions(menu);
			menu.revalidate();

			rowIndex++;
			if (rowIndex == BankTagsPlugin.BANK_ITEMS_PER_ROW)
			{
				itemX = BankTagsPlugin.BANK_ITEM_START_X;
				itemY += BankTagsPlugin.BANK_ITEM_Y_PADDING + BankTagsPlugin.BANK_ITEM_HEIGHT;
				rowIndex = 0;
			}
			else
			{
				itemX += BankTagsPlugin.BANK_ITEM_X_PADDING + BankTagsPlugin.BANK_ITEM_WIDTH;
			}
		}

		return itemY + BankTagsPlugin.BANK_ITEM_HEIGHT;
	}

	/** Hide the real bank items so the overview has the area to itself. */
	void hideBank()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.getChildren() == null)
		{
			return;
		}
		for (Widget w : items.getChildren())
		{
			if (w != null)
			{
				w.setHidden(true);
			}
		}
	}

	// ------------------------------------------------------------------
	// Hit testing, for drops
	// ------------------------------------------------------------------

	/** The row a widget stands for, or null when the widget is not one of ours. */
	@Nullable
	StripRow rowFor(@Nullable Widget widget)
	{
		return widget == null ? null : rowByWidget.get(widget);
	}

	boolean isColumnWidget(@Nullable Widget widget)
	{
		return widget != null && parent != null && widget.getParent() == parent;
	}

	/** Whether a point on the canvas falls inside our column. */
	boolean containsCanvasPoint(@Nullable Point point)
	{
		if (point == null || parent == null || parent.isHidden())
		{
			return false;
		}

		java.awt.Rectangle bounds = parent.getBounds();
		return point.getX() >= bounds.x
			&& point.getX() <= bounds.x + MARGIN + TAB_WIDTH
			&& point.getY() >= bounds.y
			&& point.getY() <= bounds.y + bounds.height;
	}

	/**
	 * Resolve a drop point to a row and a zone.
	 * <p>
	 * The outer quarter at each end of a row inserts beside it; the middle half
	 * drops into it. A quarter of a 40px tab is 10px, which is enough to hit
	 * deliberately without being easy to hit by accident.
	 */
	@Nullable
	Drop dropAt(@Nullable Point point)
	{
		if (point == null || parent == null || !initialised)
		{
			return null;
		}

		int local = point.getY() - parent.getBounds().y;

		for (RenderedRow row : rendered)
		{
			if (row.top < 0 || local < row.top || local >= row.top + row.height)
			{
				continue;
			}

			int offset = local - row.top;
			int edge = Math.max(4, row.height / 4);
			if (offset < edge)
			{
				return new Drop(row.row, DropZone.BEFORE);
			}
			if (offset >= row.height - edge)
			{
				return new Drop(row.row, DropZone.AFTER);
			}
			return new Drop(row.row, DropZone.INTO);
		}

		// Below the last row but still inside the column: append at the end.
		return null;
	}
}
